/* Vragenbank PA-toets, Wft Hypothecair Krediet. Vorm: [vraag, [[antwoord, uitleg] x4], toetsterm CDFD]; het EERSTE antwoord is steeds het juiste.
   Gegenereerd met tools/vragen-js.py. */
(window.PA_VRAGEN = window.PA_VRAGEN || {})["hypothecair-krediet"] = [
["Aan welke twee maatstaven toetst de kredietgever op grond van de Tijdelijke regeling hypothecair krediet (TRHK) de maximale hypotheek?", [["De financieringslast ten opzichte van het toetsinkomen en de verhouding lening/woningwaarde (LTV)", "De TRHK begrenst de hypotheek zowel op basis van de lasten die de consument kan dragen als op basis van de waarde van de woning."], ["Het netto besteedbaar inkomen na belasting en het totale vermogen van de consument", "De TRHK werkt met een bruto toetsinkomen en financieringslastpercentages, niet met netto inkomen of vermogen."], ["De WOZ-waarde van de woning en het aantal jaren dat de consument al onafgebroken in loondienst werkt", "De WOZ-waarde is geen hoofdmaatstaf en het dienstverband is geen wettelijke leennorm; die zijn hooguit relevant voor acceptatie."], ["De koopsom van de woning en de hoogte van de NHG-kostengrens", "De koopsom en de NHG-grens bepalen niet de wettelijke leennormen; de TRHK kijkt naar lasten en woningwaarde."]], "1a.2"],
["Een klant kiest voor een rentevaste periode van 20 jaar. Met welke rente wordt de financieringslast volgens de TRHK berekend?", [["Met de werkelijke debetrentevoet die voor die rentevaste periode in de offerte staat", "Bij een rentevaste periode van tien jaar of langer is het renterisico beperkt en wordt getoetst op de werkelijke rente."], ["Met de door de AFM vastgestelde toetsrente, ongeacht de rentevaste periode", "De AFM-toetsrente is alleen bepalend bij een rentevaste periode korter dan tien jaar."], ["Met de gemiddelde rente van de afgelopen vijf jaar voor die rentevaste periode bij deze kredietgever", "Een historisch gemiddelde speelt geen rol in de toets; het gaat om de rente van deze lening."], ["Met de werkelijke rente verhoogd met een vaste opslag van twee procentpunt", "De TRHK kent geen vaste opslag op de werkelijke rente bij lange rentevaste perioden."]], "1a.2"],
["Een klant kiest een rentevaste periode van 5 jaar. De rente in de offerte is hoger dan de actuele AFM-toetsrente. Met welke rente wordt getoetst?", [["Met de offerterente, omdat bij korte rentevastperioden de hoogste van beide geldt", "Bij een rentevaste periode korter dan tien jaar geldt de hoogste van de werkelijke rente en de toetsrente; hier is dat de offerterente."], ["Met de AFM-toetsrente, omdat die bij rentevastperioden korter dan tien jaar altijd geldt", "De toetsrente is een ondergrens; ligt de werkelijke rente hoger, dan wordt met de werkelijke rente gerekend."], ["Met het gemiddelde van de offerterente en de AFM-toetsrente", "Middelen van beide rentes is niet de systematiek; de hoogste van de twee geldt."], ["Met de laagste van beide, omdat de klant daar recht op heeft", "De toets is bedoeld om renterisico op te vangen; daarom geldt juist de hoogste, niet de laagste rente."]], "1a.2"],
["Een deel van de gevraagde hypotheek is aflossingsvrij. Hoe wordt dit deel volgens de TRHK in beginsel meegenomen in de financieringslast?", [["Alsof het annuïtair in dertig jaar wordt afgelost", "De financieringslast wordt berekend op basis van een annuïtaire aflossing over dertig jaar, ook voor delen zonder aflossingsverplichting."], ["Alleen met de werkelijk te betalen rente, zonder aflossingscomponent", "Rekenen met alleen rente zou een te hoge leencapaciteit geven; de TRHK gaat uit van een annuïtaire last."], ["Helemaal niet, omdat er tijdens de looptijd niet op wordt afgelost", "Ook een aflossingsvrij deel brengt lasten mee en telt dus mee in de toets."], ["Alsof het lineair in twintig jaar wordt afgelost", "De TRHK rekent niet met een lineaire aflossing in twintig jaar maar met een annuïteit over dertig jaar."]], "1a.2"],
["Wat legt een weduweverklaring (ook wel partnerverklaring) bij een hypotheek met een verpande verzekering vast?", [["Dat de partner instemt met de verpanding of begunstiging van de verzekering aan de geldverstrekker", "Door de verklaring kan de partner later geen rechten op de uitkering laten gelden die voorgaan op de aflossing van de lening."], ["Dat de partner na overlijden van de klant de hypotheek met de verzekeringsuitkering automatisch overneemt", "Een verklaring maakt de partner geen schuldenaar; overname vraagt een eigen beoordeling door de geldverstrekker."], ["Dat de partner recht heeft op een nabestaandenpensioen van de werkgever", "Een nabestaandenpensioen volgt uit het pensioenreglement, niet uit een verklaring bij de hypotheek."], ["Dat de partner afziet van haar recht op een Anw-uitkering ten gunste van de bank", "Een Anw-uitkering is een persoonlijk recht van de nabestaande en kan niet aan de bank worden afgestaan."]], "1b.8"],
["Waarom rekent de TRHK met bruto woonlasten (rente en aflossing vóór belasting) en niet met netto lasten?", [["Omdat het fiscale effect van de renteaftrek al in de financieringslastpercentages zit", "De tabellen houden rekening met de belastingdruk en de aftrek, zodat de toets op bruto lasten plaatsvindt."], ["Omdat hypotheekrente sinds 2013 niet meer aftrekbaar is", "Hypotheekrente op een eigenwoningschuld is nog steeds aftrekbaar, mits aan de voorwaarden wordt voldaan."], ["Omdat de kredietgever het fiscale voordeel van de klant volgens de AVG niet mag meewegen", "De kredietgever mag fiscale informatie wel kennen en gebruiken; het netto effect zit al in de percentages."], ["Omdat netto lasten pas na de eerste aangifte inkomstenbelasting definitief vaststaan", "Netto lasten zijn vooraf goed te berekenen; de reden is dat de percentages al op bruto lasten zijn afgestemd."]], "1a.2"],
["Een woning staat op erfpachtgrond waarvoor jaarlijks canon wordt betaald. Hoe telt de canon mee bij de leennormen?", [["De canon telt als vaste last mee in de financieringslast, naast rente en aflossing", "De TRHK rekent erfpachtcanon tot de jaarlijkse lasten, naast rente en aflossing."], ["De canon wordt opgeteld bij de woningwaarde voor de LTV", "Canon is een last en geen waardebestanddeel; erfpacht verlaagt eerder de marktwaarde."], ["De canon is alleen relevant voor de taxateur en niet voor de leennormen", "Canon raakt ook de betaalbaarheid en is daarom onderdeel van de financieringslast."], ["De canon verhoogt het toetsinkomen omdat zij fiscaal aftrekbaar is", "Canon verhoogt het toetsinkomen niet; het is juist een extra last voor de consument."]], "1a.2"],
["Wat houdt 'explain' bij de leennormen in?", [["De kredietgever mag verantwoord afwijken, mits gemotiveerd en vastgelegd", "De TRHK staat afwijking toe als die op basis van de persoonlijke situatie verantwoord is; de onderbouwing moet worden vastgelegd."], ["De adviseur legt de klant schriftelijk uit hoe de maximale hypotheek is berekend", "Uitleg aan de klant is goede dienstverlening, maar 'explain' is de bevoegdheid van de kredietgever om gemotiveerd af te wijken."], ["De klant mag zelf afwijken van de normen door een verklaring te tekenen", "De consument kan niet zelf de normen buiten werking stellen; de afwijking is een verantwoorde beslissing van de kredietgever."], ["De AFM keurt vooraf elke afwijking van de leennormen goed", "De AFM keurt individuele dossiers niet vooraf goed; zij houdt achteraf toezicht op het gebruik van explain."]], "1a.2"],
["Ellen (54) en Rob (56) wonen al twintig jaar in hun rijtjeshuis in Zwolle en hebben een hypotheek van € 280.000. Rob is vorig jaar na een reorganisatie aan een lager betaalde baan begonnen, waardoor hun gezamenlijke inkomen flink is gedaald. Hun rentevaste periode loopt bijna af en een andere geldverstrekker biedt een lagere rente. Zij willen oversluiten zonder de lening te verhogen, maar bij hun huidige inkomen past € 280.000 niet meer binnen de leennormen. Wat is juist?", [["Via explain kan de kredietgever afwijken: zij sluiten over zonder verhoging en hun lasten dalen", "Oversluiten zonder verhoging waarbij de lasten dalen is een erkende situatie waarin afwijken van de leennormen verantwoord kan zijn, mits gemotiveerd vastgelegd."], ["Oversluiten is niet toegestaan zolang hun lening niet binnen de huidige leennormen past", "Er geldt geen absoluut verbod; juist voor deze situatie biedt explain ruimte."], ["Zij moeten eerst het deel boven de nieuwe norm aflossen, uit eigen geld of met een schenking", "Een verplichte aflossing is niet vereist als afwijken verantwoord is en wordt onderbouwd."], ["De leennormen gelden bij oversluiten alleen voor de rente en niet voor de hoogte van de bestaande lening", "De TRHK toetst de hele lening; afwijken van de normen kan alleen via explain."]], "1a.2"],
["Lisa (29) werkt als fysiotherapeut en wil haar eerste woning kopen, een appartement in Arnhem. De taxateur stelt de marktwaarde vast op € 350.000; dat is ook de koopsom. De kosten koper komen uit op € 8.000 en zij wil geen energiebesparende maatregelen meefinancieren. Haar inkomen is ruim voldoende voor de financieringslast. Wat is volgens de LTV-norm haar maximale hypotheek?", [["€ 350.000; de kosten koper van € 8.000 moet zij uit eigen geld betalen", "Bij een LTV van maximaal 100% van de marktwaarde is € 350.000 het maximum; kosten koper vallen daarbuiten."], ["€ 358.000, omdat kosten koper altijd mogen worden meegefinancierd", "Meefinancieren van kosten koper boven de marktwaarde past niet binnen de LTV-norm van 100%."], ["€ 371.000, omdat de LTV bij starters 106% van de marktwaarde mag zijn", "Een LTV boven 100% gold alleen tijdens de afbouw tot 2018; voor starters bestaat geen hogere hoofdregel."], ["€ 342.000, omdat de kosten koper eerst van de marktwaarde worden afgetrokken", "De kosten koper verlagen de toegestane hypotheek niet; ze moeten alleen uit eigen middelen komen."]], "1a.2"],
["Een klant leent € 315.000 op een woning met een marktwaarde van € 350.000. Wat is de loan-to-value (LTV)?", [["90%", "€ 315.000 gedeeld door € 350.000 is 0,90, dus een LTV van 90%."], ["111%", "Dat is de omgekeerde verhouding (waarde gedeeld door lening), niet de LTV."], ["10%", "10% is het deel van de woningwaarde dat niet is gefinancierd, niet de LTV."], ["85%", "85% van € 350.000 is € 297.500; de lening is hoger, dus de LTV is 90%."]], "1a.2"],
["Wat geldt in de TRHK voor consumenten die de AOW-leeftijd hebben bereikt?", [["Voor hen gelden aparte financieringslastpercentages", "De TRHK bevat afzonderlijke tabellen voor AOW-gerechtigden, afgestemd op hun andere belastingdruk en uitgaven."], ["Zij mogen geen nieuwe hypotheek meer afsluiten", "Er geldt geen leeftijdsverbod; ook na de AOW-leeftijd kan een hypotheek verantwoord zijn."], ["Voor hen geldt altijd een maximale LTV van 50%", "De TRHK kent geen lagere LTV-grens op basis van leeftijd."], ["Hun AOW-uitkering telt niet mee als toetsinkomen", "AOW en pensioen tellen juist mee als inkomen bij de toets."]], "1a.2"],
["Voor wie is de Gedragscode Hypothecaire Financieringen (GHF) bindend?", [["Voor geldverstrekkers die zich via hun brancheorganisatie aan de code hebben verbonden", "De GHF is zelfregulering; zij bindt de aangesloten aanbieders, zoals banken en verzekeraars die de code onderschrijven."], ["Voor iedere consument die een hypotheek afsluit", "Een gedragscode bindt de partijen die zich eraan verbinden, niet de consument."], ["Voor alle Nederlandse notarissen bij het opstellen en passeren van hypotheekakten voor consumenten", "Notarissen hebben hun eigen beroepsregels; de GHF is gericht op geldverstrekkers."], ["Alleen voor hypotheekadviseurs met een AFM-vergunning", "De GHF is opgesteld door en voor geldverstrekkers, niet primair voor adviseurs."]], "1a.3"],
["Een hypotheek heeft een nominale rente van 4% per jaar, die in twaalf maandtermijnen wordt betaald. Wat is juist over de effectieve jaarrente?", [["Die ligt iets hoger dan 4%, omdat de rente in maandtermijnen eerder wordt betaald", "Door maandelijkse betaling werkt de rente als samengestelde rente; de effectieve jaarrente komt uit op ongeveer 4,07%."], ["Die is precies 4%, omdat de rente per jaar is afgesproken", "Het moment van betalen beïnvloedt de effectieve rente; maandelijks betalen maakt die iets hoger."], ["Die ligt iets lager dan 4%, omdat de klant elke maand ook een deel van de lening aflost", "Aflossing verlaagt het rentebedrag in euro's, niet het effectieve rentepercentage."], ["Die is 48%, omdat er twaalf keer per jaar 4% wordt berekend", "Per maand wordt een twaalfde van de jaarrente berekend, dus ongeveer 0,33% per maand."]], "1e.1"],
["Waarop ziet de huidige Gedragscode Hypothecaire Financieringen vooral?", [["Minimumeisen aan de offerte, de voorwaarden en de informatie over kosten en rente", "De GHF regelt onder meer wat in een offerte moet staan en hoe de aanbieder informeert over voorwaarden, kosten en rente."], ["De hoogte van de financieringslastpercentages per inkomensklasse en per toetsrente", "Die percentages staan in de TRHK, niet in de GHF."], ["De fiscale voorwaarden voor aftrek van hypotheekrente", "De fiscale regels staan in de Wet IB 2001."], ["De voorwaarden voor kwijtschelding van een restschuld met NHG", "Die voorwaarden staan in de Voorwaarden & Normen van de NHG."]], "1a.3"],
["Bij een annuïteitenhypotheek met een gelijkblijvende rente stijgen de netto maandlasten in de loop van de tijd. Wat is daarvan de oorzaak?", [["Het rentedeel daalt, waardoor de renteaftrek en dus het fiscale voordeel afnemen", "De bruto annuïteit blijft gelijk, maar omdat het aftrekbare rentedeel daalt, stijgt de netto last."], ["Het aflossingsdeel wordt elk jaar door de geldverstrekker verhoogd volgens een vast schema", "Het aflossingsdeel groeit vanzelf binnen dezelfde bruto annuïteit; de bruto last stijgt niet."], ["De rente wordt automatisch aan de inflatie aangepast", "Bij een vaste rente vindt geen inflatiecorrectie plaats."], ["Het eigenwoningforfait daalt elk jaar mee met de resterende hypotheekschuld", "Het forfait hangt af van de WOZ-waarde, niet van de schuld."]], "1h.2"],
["Een klant vergelijkt een annuïtaire en een lineaire hypotheek van hetzelfde bedrag, met dezelfde looptijd en rente. Wat is juist?", [["Bij lineair betaalt hij in totaal minder rente, maar zijn de aanvangslasten hoger", "Bij lineair daalt de schuld in het begin sneller, waardoor minder rente wordt betaald; daar staan hogere startlasten tegenover."], ["Bij lineair betaalt hij over de hele looptijd meer rente, maar de aanvangslasten zijn juist lager", "Het is andersom: lineair begint hoger en kost in totaal minder rente."], ["Beide vormen kosten over de hele looptijd evenveel rente", "Omdat de schuld bij lineair sneller daalt, is de totale rente lager."], ["Alleen de annuïtaire vorm voldoet aan de fiscale aflossingseis van minimaal annuïtair in 30 jaar", "Lineair aflossen is sneller dan annuïtair en voldoet dus ook aan de aflossingseis."]], "1i.3"],
["Een klant sluit een lineaire hypotheek van € 240.000 af met een looptijd van 30 jaar en een rente van 4,8%. Wat is de bruto maandlast in de eerste maand?", [["€ 1.626,67", "De aflossing is € 240.000 / 360 = € 666,67 en de rente € 240.000 × 4,8% / 12 = € 960,00; samen € 1.626,67."], ["€ 1.259,20", "Dit is ongeveer de bruto annuïteit voor dezelfde lening, niet de lineaire aanvangslast."], ["€ 960,00", "Dit is alleen het rentedeel; bij lineair komt de vaste aflossing daar nog bij."], ["€ 666,67", "Dit is alleen het vaste aflossingsdeel; de rente moet er nog bij worden opgeteld."]], "1i.3"],
["Een klant heeft een aflossingsvrij leningdeel van € 180.000 tegen een rente van 3,9%. Wat is de bruto maandlast van dit leningdeel?", [["€ 585,00", "€ 180.000 × 3,9% = € 7.020 per jaar; gedeeld door 12 is dat € 585,00 per maand."], ["€ 702,00", "Dit is het jaarbedrag gedeeld door 10 in plaats van door 12."], ["€ 1.085,00", "Bij aflossingsvrij wordt niet afgelost; er komt dus geen aflossingsbedrag bij de rente."], ["€ 7.020,00", "Dit is de rente per jaar, niet per maand."]], "1i.3"],
["Wat kenmerkt een bankspaarhypotheek?", [["Er wordt gespaard op een geblokkeerde rekening die aan het einde de lening aflost", "De lening zelf is aflossingsvrij; de inleg op de geblokkeerde spaarrekening eigen woning wordt aan het einde gebruikt voor aflossing."], ["De lening wordt maandelijks lineair afgelost via een gewone, vrij opneembare bankrekening bij dezelfde bank", "Bij bankspaar wordt niet tussentijds op de lening afgelost; er wordt apart gespaard."], ["De inleg wordt belegd in fondsen naar keuze van de klant", "Dat is een beleggingshypotheek; bij bankspaar wordt gespaard tegen een rente."], ["De klant betaalt alleen rente en bouwt geen spaartegoed op", "Dat is een aflossingsvrije hypotheek zonder spaarcomponent."]], "1e.2"],
["Voor een kapitaalverzekering eigen woning of spaarrekening eigen woning onder het overgangsrecht geldt een bandbreedte voor de inleg. Wat houdt die in?", [["De hoogste jaarinleg is maximaal tien keer de laagste", "De bandbreedte 1:10 voorkomt dat de inleg sterk wordt geconcentreerd, als voorwaarde voor de vrijstelling."], ["De inleg moet elk jaar precies gelijk zijn", "Variatie is toegestaan, zolang de verhouding 1:10 niet wordt overschreden."], ["De inleg mag maximaal tien jaar duren", "De bandbreedte gaat over de hoogte van de inleg, niet over de duur."], ["De uitkering mag maximaal tien keer de jaarpremie bedragen", "De bandbreedte gaat over de verhouding tussen de premies onderling, niet over de uitkering."]], "1e.12"],
["Wat is het doel van een overbruggingskrediet bij de aankoop van een nieuwe woning?", [["Tijdelijk de overwaarde van de oude, nog onverkochte woning beschikbaar maken voor de nieuwe", "Het overbruggingskrediet financiert de periode tussen aankoop van de nieuwe en verkoop van de oude woning."], ["De kosten koper van de nieuwe woning permanent meefinancieren boven de marktwaarde van de nieuwe woning", "Een overbrugging is tijdelijk en bedoeld voor de overwaarde, niet om kosten koper blijvend te financieren."], ["De rentevaste periode van de oude hypotheek verlengen tot de verkoop", "Een overbrugging verandert niets aan de rentevaste periode van de bestaande lening."], ["Een eventuele restschuld van de oude woning blijvend financieren", "Een restschuld is geen overwaarde; een overbrugging gaat juist uit van overwaarde."]], "1e.3"],
["Welk risico is kenmerkend voor een beleggingshypotheek?", [["Het belegde vermogen kan aan het einde onvoldoende zijn om de lening af te lossen", "Bij tegenvallende rendementen ontstaat een tekort, waardoor aan het einde een deel van de schuld blijft staan."], ["De hypotheekrente stijgt automatisch mee met de koersen van de fondsen waarin de klant belegt", "De hypotheekrente staat los van de beleggingsresultaten."], ["De lening wordt bij koersdaling direct opeisbaar", "Een koersdaling maakt de hypotheek niet automatisch opeisbaar."], ["De klant betaalt over de looptijd dubbel overdrachtsbelasting, bij aankoop en bij aflossing", "Overdrachtsbelasting heeft niets te maken met de hypotheekvorm."]], "1e.2"],
["Thijs (27) is software-ontwikkelaar en verdient € 55.000 bruto per jaar. Hij koopt in 2026 zijn eerste woning, een appartement in Eindhoven. Om de maandlasten laag te houden wil hij de hele hypotheek aflossingsvrij afsluiten. Hij denkt dat hij de rente gewoon kan aftrekken, zoals zijn ouders dat jaren hebben gedaan. Wat is het fiscale gevolg van zijn keuze?", [["Er is geen eigenwoningschuld: de rente is niet aftrekbaar en de schuld valt in box 3", "Sinds 2013 is voor renteaftrek nodig dat een nieuwe lening minimaal annuïtair in 30 jaar wordt afgelost; een aflossingsvrije lening valt in box 3."], ["De rente is aftrekbaar, maar tegen een lager tarief dan bij een annuïtaire hypotheek", "Er bestaat geen apart, lager aftrektarief voor aflossingsvrije leningen; de rente is helemaal niet aftrekbaar."], ["De rente is de eerste tien jaar aftrekbaar en daarna niet meer", "Een overgangstermijn van tien jaar bestaat niet; zonder aflossingseis is er vanaf het begin geen aftrek."], ["De rente is aftrekbaar zolang hij elk jaar vrijwillig iets extra aflost", "Vrijwillige extra aflossingen zijn niet genoeg; de lening moet volgens de overeenkomst minimaal annuïtair in 30 jaar worden afgelost."]], "1a.1"],
["Wat houdt het overgangsrecht voor bestaande eigenwoningschulden per 31 december 2012 in?", [["Die schulden behouden recht op renteaftrek zonder aan de aflossingseis te hoeven voldoen", "Wie op 31 december 2012 al een eigenwoningschuld had, valt voor dat bedrag niet onder de verplichting om annuïtair af te lossen."], ["Die schulden moeten alsnog vóór 2030 volledig zijn afgelost om de renteaftrek te behouden", "Het overgangsrecht kent geen verplichte aflossing vóór een bepaald jaar."], ["Die schulden zijn vanaf 2013 onbeperkt in tijd aftrekbaar", "Ook onder het overgangsrecht blijft de maximale aftrekperiode van 30 jaar gelden."], ["Die schulden mogen onbeperkt worden verhoogd met behoud van overgangsrecht", "Een verhoging na 2012 valt onder de nieuwe regels en moet aan de aflossingseis voldoen."]], "1a.1"],
["Henk (61) en Marja (59) wonen sinds 2009 in een vrijstaande woning in Ede, gefinancierd met een aflossingsvrije hypotheek van € 200.000. Henk werkt nog als accountmanager, Marja is parttime administratief medewerker. Zij willen in 2026 de badkamer en keuken vernieuwen en lenen daarvoor € 40.000 bij. Zij hopen dat het nieuwe deel ook aflossingsvrij kan, net als de rest. Wat geldt voor het nieuwe leningdeel als zij de rente willen aftrekken?", [["Het nieuwe deel moet minimaal annuïtair in 30 jaar worden afgelost; het oude deel mag aflossingsvrij blijven", "Het overgangsrecht beschermt alleen de bestaande schuld van vóór 2013; voor nieuwe eigenwoningschuld geldt de aflossingseis."], ["Het nieuwe deel mag ook aflossingsvrij blijven, omdat het oude deel van vóór 2013 onder het overgangsrecht valt", "Het overgangsrecht geldt niet voor een verhoging; die moet aan de aflossingseis voldoen."], ["De hele lening van € 240.000 moet nu annuïtair in de resterende looptijd worden afgelost", "Het oude deel houdt zijn overgangsrecht; alleen het nieuwe deel moet worden afgelost."], ["Rente over een lening voor een verbouwing is nooit aftrekbaar, alleen rente voor de aankoop", "Een lening voor verbetering of onderhoud van de eigen woning kan wel eigenwoningschuld zijn."]], "1a.1"],
["Karin (44) en Joost (46) verkopen hun tussenwoning in Amersfoort voor € 420.000; de verkoopkosten bedragen € 12.000. Hun eigenwoningschuld is € 260.000. Zij kopen een vrijstaande woning van € 525.000 met € 23.000 kosten koper. Zij willen zoveel mogelijk lenen en hun overwaarde op een spaarrekening zetten. Wat is hun maximale nieuwe eigenwoningschuld?", [["€ 400.000", "De eigenwoningreserve is € 420.000 − € 12.000 − € 260.000 = € 148.000; de verwervingskosten zijn € 548.000; € 548.000 − € 148.000 = € 400.000."], ["€ 388.000", "Hier zijn de verkoopkosten vergeten, waardoor de eigenwoningreserve te hoog (€ 160.000) is berekend."], ["€ 377.000", "Hier zijn de kosten koper niet meegenomen in de verwervingskosten van de nieuwe woning."], ["€ 548.000", "Hier is de eigenwoningreserve genegeerd; volgens de bijleenregeling moet de overwaarde worden ingebracht, anders valt dat deel in box 3."]], "1h.4"],
["Ruud (38) verkocht begin 2022 zijn appartement in Den Haag met een overwaarde van € 60.000. Hij ging voor zijn werk in het buitenland wonen en huurde daar. Eind 2026 komt hij terug en koopt hij een woning in Leiden. Hij vraagt zich af of hij de oude overwaarde nog moet inbrengen. Wat is fiscaal juist?", [["De eigenwoningreserve is na drie jaar vervallen; hij hoeft de oude overwaarde niet meer in te brengen", "Een eigenwoningreserve geldt drie jaar na de vervreemding; daarna vervalt zij."], ["Hij moet de overwaarde alsnog volledig inbrengen, omdat de reserve nooit vervalt", "De reserve vervalt wel: na drie jaar hoeft de overwaarde niet meer te worden ingebracht."], ["Hij heeft voor de nieuwe woning geen recht op renteaftrek, omdat hij een aantal jaren in het buitenland woonde", "Wonen in het buitenland sluit renteaftrek voor een nieuwe eigen woning in Nederland niet uit."], ["De overwaarde wordt na drie jaar alsnog belast in box 1 van zijn aangifte", "Het vervallen van de reserve leidt niet tot belasting in box 1; de reserve verdwijnt gewoon."]], "1a.1"],
["Welke kosten zijn bij de aankoop van een eigen woning direct aftrekbaar als financieringskosten in box 1?", [["De advies- en bemiddelingskosten voor de hypotheek", "Kosten die samenhangen met het afsluiten van de lening, zoals advies, taxatie voor de lening en de hypotheekakte, zijn aftrekbaar."], ["De overdrachtsbelasting", "Overdrachtsbelasting is een verwervingskost van de woning, geen financieringskost, en dus niet aftrekbaar."], ["De notariskosten van de leveringsakte bij de overdracht", "De leveringsakte hoort bij de verwerving van de woning; alleen de hypotheekakte is aftrekbaar."], ["De kosten van de aankoopmakelaar en de bouwkundige keuring", "Makelaarskosten zijn verwervingskosten en niet aftrekbaar als financieringskosten."]], "1e.7"],
["Hoe werkt het eigenwoningforfait in de inkomstenbelasting?", [["Als bijtelling in box 1, berekend als percentage van de WOZ-waarde", "Het forfait is het fiscale voordeel van het wonen in de eigen woning; aftrekbare rente en kosten worden ervan afgetrokken."], ["Als aftrekpost die het belastbaar inkomen uit werk en woning in box 1 verlaagt", "Het forfait verhoogt juist het inkomen; de rente is de aftrekpost."], ["Als gemeentelijke belasting die jaarlijks wordt geheven", "Gemeenten heffen OZB; het forfait is onderdeel van de inkomstenbelasting."], ["Als percentage van de hypotheekschuld, belast in box 3", "Het forfait hangt af van de WOZ-waarde en valt in box 1, niet in box 3."]], "1h.4"],
["Een klant heeft zijn hypotheek volledig afgelost en woont nog in de woning. Wat geldt voor de aftrek wegens geen of geringe eigenwoningschuld (Wet Hillen)?", [["Hij krijgt een aftrek die het forfait deels compenseert en wordt afgebouwd", "Sinds 2019 wordt de Hillen-aftrek in dertig jaar afgebouwd, waardoor een steeds groter deel van het forfait wordt belast."], ["Het eigenwoningforfait vervalt omdat er geen schuld meer is", "Het forfait blijft bestaan zolang de woning het hoofdverblijf is, ook zonder schuld."], ["Hij mag het volledige forfait voor altijd buiten de heffing laten", "Dat was het effect vóór 2019; de compensatie wordt nu afgebouwd."], ["Hij krijgt een teruggave van de rente die hij in het verleden heeft betaald", "De Wet Hillen gaat over het forfait, niet over teruggave van betaalde rente."]], "1h.4"],
["Fatima (36) en Youssef (39) hebben een nieuwe woning in Almere gekocht en zijn verhuisd. Hun oude appartement in Amsterdam staat leeg en te koop, maar een koper is nog niet gevonden. Beide woningen hebben een hypotheek. Zij vragen hoe lang zij de rente over de oude woning nog mogen aftrekken. Hoe lang kan de oude woning fiscaal als eigen woning blijven gelden?", [["In het jaar waarin zij leeg kwam te staan en de drie jaren daarna, zolang zij te koop staat", "Een leegstaande woning die te koop staat, blijft gedurende die periode eigen woning."], ["Tot het einde van de maand waarin zij met hun gezin naar de nieuwe woning in Almere zijn verhuisd", "De wet geeft juist een langere periode om de woning te verkopen."], ["Maximaal zes maanden na de verhuizing, daarna valt de woning in box 3", "Een termijn van zes maanden bestaat niet; de periode is het jaar van leegkomen plus drie jaar."], ["Onbeperkt, zolang de woning maar aantoonbaar te koop staat", "De periode is beperkt; daarna valt de woning met de schuld in box 3."]], "1e.11"],
["Bram (30) en Eva (28) huren een appartement in Groningen. Zij kopen een nieuwbouwwoning in een project aan de rand van de stad die over anderhalf jaar wordt opgeleverd. Tot de oplevering blijven zij in hun huurhuis wonen en betalen zij al rente over hun nieuwe hypotheek. Zij willen weten of die rente aftrekbaar is. Wat geldt?", [["De woning kan al eigen woning zijn als zij die naar verwachting binnen drie jaar gaan bewonen", "Een woning in aanbouw die binnen drie jaar als hoofdverblijf wordt betrokken, kan al als eigen woning gelden."], ["De rente is pas aftrekbaar vanaf de dag dat zij op het nieuwe adres zijn ingeschreven", "Inschrijving is niet beslissend; de wet kent een regeling voor woningen in aanbouw."], ["Bouwrente is nooit aftrekbaar; alleen de hypotheekrente na de oplevering telt mee", "Ook rente in de bouwperiode kan aftrekbaar zijn als aan de voorwaarden wordt voldaan."], ["Tot de oplevering valt de lening in box 3, omdat de woning nog niet bestaat", "Dankzij de regeling voor woningen in aanbouw hoeft de lening niet in box 3 te vallen."]], "1a.1"],
["Wat geldt voor de rente over een restschuld na verkoop van een eigen woning?", [["Alleen bij ontstaan tussen 29-10-2012 en 31-12-2017: maximaal 15 jaar aftrek", "Deze tijdelijke regeling is beëindigd; voor later ontstane restschulden is de rente niet meer aftrekbaar."], ["Rente over iedere restschuld is altijd 30 jaar aftrekbaar", "Een restschuld is geen eigenwoningschuld; alleen de tijdelijke regeling gaf beperkte aftrek."], ["Rente over een restschuld is aftrekbaar als de klant opnieuw een woning koopt", "Een nieuwe aankoop maakt een restschuld niet tot eigenwoningschuld."], ["Rente over een restschuld is alleen aftrekbaar bij een NHG-hypotheek", "NHG kan een restschuld kwijtschelden, maar regelt geen renteaftrek."]], "1e.9"],
["Mark (42) is installatiemonteur en woont met zijn gezin in een twee-onder-een-kapwoning in Apeldoorn. Zijn hypotheek is € 210.000, terwijl de woning inmiddels € 420.000 waard is. Hij wil de hypotheek met € 25.000 verhogen om een elektrische auto te kopen, omdat de hypotheekrente lager is dan de rente op een autolening. Hij gaat ervan uit dat hij die rente kan aftrekken. Hoe wordt het nieuwe leningdeel fiscaal behandeld?", [["Het valt in box 3, omdat het geld niet aan de eigen woning wordt besteed", "Alleen leningen voor aankoop, verbetering of onderhoud van de eigen woning zijn eigenwoningschuld."], ["Het is aftrekbaar, omdat op de woning een hypotheekrecht is gevestigd", "Het hypotheekrecht is een zekerheid en bepaalt niet de fiscale behandeling; de besteding is beslissend."], ["Het is aftrekbaar, mits hij het annuïtair in dertig jaar aflost", "De aflossingseis is een extra voorwaarde, maar het geld moet ook aan de woning worden besteed."], ["Het valt in box 2, omdat een auto een vermogensbestanddeel is", "Box 2 gaat over een aanmerkelijk belang in een vennootschap, niet over privéschulden."]], "1a.1"],
["Peter (58) en Annemiek (57) wonen in een vrijstaande woning in Hilversum. Nu de kinderen het huis uit zijn, kopen zij een vakantiewoning in Zeeland, waar zij ongeveer tien weekenden per jaar verblijven. Zij financieren die woning met een aparte hypotheek bij hun eigen bank. Zij hopen ook die rente te kunnen aftrekken. Wat is juist?", [["De vakantiewoning en de lening vallen in box 3; de rente is niet aftrekbaar in box 1", "Alleen het hoofdverblijf is eigen woning; een tweede woning valt met de schuld in box 3."], ["Beide woningen gelden als eigen woning, omdat zij er allebei regelmatig en langere tijd verblijven", "Er kan maar één eigen woning zijn: het hoofdverblijf."], ["De rente over de vakantiewoning is aftrekbaar, maar tegen een lager tarief", "Voor een tweede woning is er geen renteaftrek in box 1, ook niet tegen een lager tarief."], ["Over de vakantiewoning betalen zij eigenwoningforfait in plaats van box 3-heffing", "Het eigenwoningforfait geldt alleen voor de eigen woning (het hoofdverblijf)."]], "1h.4"],
["Daan (26) is net begonnen als jurist en koopt een appartement in Nijmegen. Zijn ouders lenen hem € 50.000 van hun spaargeld, zodat hij minder bij de bank hoeft te lenen. Zij spreken een marktconforme rente af en leggen de lening schriftelijk vast. Daan wil de rente die hij aan zijn ouders betaalt aftrekken. Wat is daarvoor onder meer vereist?", [["Dat de lening minimaal annuïtair in 30 jaar wordt afgelost en hij de leninggegevens in zijn aangifte vermeldt", "Ook voor een familielening gelden de aflossingseis en de informatieplicht; anders valt de schuld in box 3."], ["Dat de lening via de notaris wordt vastgelegd en daarnaast onder de NHG-borgtocht van de Stichting WEW wordt gebracht", "Een notariële akte of NHG is geen voorwaarde voor renteaftrek op een familielening."], ["Dat zijn ouders als kredietgever een vergunning van de AFM hebben", "Particulieren die eenmalig aan hun kind lenen, hebben geen vergunning nodig."], ["Dat de lening aflossingsvrij is, zodat er geen schenking ontstaat", "Een aflossingsvrije lening voldoet juist niet aan de aflossingseis."]], "1e.3"],
["Twee fiscale partners bezitten samen hun eigen woning. Hoe mogen zij het saldo van eigenwoningforfait en aftrekbare kosten verdelen?", [["In elke gewenste verhouding tussen beide partners", "Fiscale partners mogen gemeenschappelijke bestanddelen, zoals het saldo eigen woning, in elke gewenste verhouding verdelen."], ["Altijd verplicht bij helfte, ongeacht wie de rente betaalt", "Verdeling bij helfte is niet verplicht voor fiscale partners."], ["Volledig bij de partner met het laagste inkomen", "Er is geen verplichting om het saldo bij de partner met het laagste inkomen te leggen."], ["Naar rato van de eigendomsverhouding in de leveringsakte", "Voor fiscale partners is de eigendomsverhouding niet bepalend voor de verdeling."]], "1h.4"],
["Een klant sluit een in 2016 afgesloten annuïtaire eigenwoningschuld over naar een andere geldverstrekker. Wat geldt fiscaal voor de nieuwe lening?", [["Het aflossingsschema en de resterende looptijd van de oude lening lopen door", "Bij oversluiten loopt het oorspronkelijke aflossingsschema door; de klant krijgt geen nieuwe periode van 30 jaar."], ["Er begint een nieuwe looptijd van 30 jaar voor renteaftrek", "Oversluiten geeft geen nieuwe aftrekperiode; de al verstreken looptijd telt mee."], ["De nieuwe lening mag aflossingsvrij zijn als de rente lager is", "Een lagere rente verandert niets aan de aflossingseis."], ["De nieuwe lening valt automatisch onder het overgangsrecht voor schulden van vóór 2013", "Een lening uit 2016 heeft nooit overgangsrecht gehad."]], "1a.1"],
["Chantal (42) en Erwin (45) kopen een vrijstaande woning in Doetinchem voor € 450.000, waarvan ongeveer € 150.000 grondwaarde. Hun geldverstrekker eist een opstalverzekering. Erwin wil de woning verzekeren voor de koopsom, zodat alles gedekt is. De adviseur legt uit hoe het verzekerde bedrag hoort te worden vastgesteld. Op welke waarde moet de verzekerde som van de opstalverzekering worden gebaseerd?", [["Op de herbouwwaarde: wat het kost om de woning na volledige schade opnieuw op te bouwen", "De grond gaat bij brand niet verloren; de verzekering dekt het herbouwen van de opstal, dus de herbouwwaarde is de maatstaf."], ["Op de koopsom van € 450.000, inclusief de grond onder de woning", "De grond hoeft niet te worden verzekerd; verzekeren op de koopsom leidt meestal tot oververzekering."], ["Op de WOZ-waarde die de gemeente jaarlijks voor de woning vaststelt", "De WOZ-waarde is een waarde inclusief grond voor de belastingheffing, geen herbouwwaarde."], ["Op de hoogte van de hypotheek, zodat de geldverstrekker bij schade aan de woning volledig is gedekt", "De schuld zegt niets over de kosten van herbouw; de verzekering moet aansluiten bij de woning zelf."]], "3c.6"],
["Waarom krijgt een klant met NHG doorgaans een lagere rente?", [["Omdat de borgtocht het risico voor de geldverstrekker verkleint", "De borgtocht beperkt het verlies van de geldverstrekker bij gedwongen verkoop; dat lagere risico wordt in de rente doorgegeven."], ["Omdat de overheid een deel van de rente rechtstreeks betaalt", "Er is geen rentesubsidie; het voordeel komt voort uit het lagere risico."], ["Omdat NHG-hypotheken niet onder de TRHK vallen", "NHG-hypotheken vallen gewoon onder de TRHK, met aanvullende NHG-normen."], ["Omdat bij NHG geen hypotheekrecht wordt gevestigd", "Ook bij NHG wordt een hypotheekrecht gevestigd; NHG komt daar bovenop."]], "1b.3"],
["Jeroen (41) en Sabine (40) kochten in 2019 een woning in Breda met NHG. Na hun scheiding kan geen van beiden de woning alleen betalen, dus wordt zij verkocht. De opbrengst is lager dan de hypotheek, zodat een restschuld overblijft. Zij hebben de geldverstrekker tijdig ingelicht en verkopen in overleg tegen een reële prijs. Wanneer kan de Stichting WEW de restschuld kwijtschelden?", [["Bij een erkende oorzaak zoals een scheiding, mits zij verantwoord hebben gehandeld", "Kwijtschelding is mogelijk bij oorzaken als relatie-einde, werkloosheid, arbeidsongeschiktheid of overlijden, mits de klant zich verantwoord heeft opgesteld."], ["Altijd, ongeacht de oorzaak van de verkoop en het gedrag van de klanten", "Kwijtschelding is geen automatisme; de oorzaak en het gedrag van de klant worden beoordeeld."], ["Alleen als een van beiden de AOW-leeftijd heeft bereikt en geen pensioenvermogen heeft", "Leeftijd is geen voorwaarde voor kwijtschelding."], ["Nooit, omdat NHG alleen de geldverstrekker beschermt en niet de consument", "NHG beschermt ook de consument, die onder voorwaarden geen restschuld hoeft te betalen."]], "1e.9"],
["Hoe ontwikkelt de NHG-borgtocht zich tijdens de looptijd?", [["De borgtocht daalt elke maand alsof de lening annuïtair in 30 jaar wordt afgelost", "De dekking neemt af volgens een annuïtair schema, ook als de lening in werkelijkheid anders wordt afgelost."], ["De borgtocht blijft de hele looptijd gelijk aan het oorspronkelijke leenbedrag met NHG", "De borgtocht daalt juist in de tijd."], ["De borgtocht stijgt mee met de woningwaarde", "De borgtocht volgt een vast afbouwschema, niet de woningwaarde."], ["De borgtocht vervalt automatisch na tien jaar", "De borgtocht loopt in beginsel de hele looptijd, maar daalt wel."]], "1b.3"],
["Hoe wordt de eenmalige borgtochtprovisie voor NHG fiscaal behandeld?", [["Als aftrekbare financieringskosten van de eigenwoningschuld", "De NHG-provisie is een kostenpost voor het verkrijgen van de lening en is daarom aftrekbaar in box 1."], ["Als verwervingskost van de woning die niet aftrekbaar is in box 1", "De provisie hoort bij de financiering, niet bij de verwerving van de woning."], ["Als premie die in box 3 wordt vrijgesteld", "Box 3 speelt hier geen rol; het gaat om aftrekbare kosten in box 1."], ["Als schenking aan de Stichting WEW, aftrekbaar als gift", "De provisie is een vergoeding voor de borgtocht, geen schenking."]], "1e.7"],
["Wat wordt in een taxatierapport voor hypothecaire financiering verstaan onder de marktwaarde?", [["De geschatte prijs bij verkoop tussen een bereidwillige koper en verkoper", "De marktwaarde gaat uit van een zakelijke transactie na behoorlijke marketing, waarbij partijen zonder dwang handelen."], ["Het bedrag dat bij een executieveiling van de woning minimaal wordt opgebracht", "Dat is de executiewaarde of veilingwaarde, die doorgaans lager ligt."], ["De WOZ-waarde die de gemeente heeft vastgesteld", "De WOZ-waarde is een fiscale waarde met een andere peildatum en doelstelling."], ["De koopsom uit de koopovereenkomst", "De koopsom kan afwijken van de marktwaarde; de taxateur stelt zelfstandig de waarde vast."]], "1b.3"],
["Wat is de rol van een validatie-instituut bij een taxatierapport?", [["Het controleert of het rapport volgens de normen is opgesteld", "Validatie toetst kwaliteit en onderbouwing van het rapport, zodat de geldverstrekker erop kan vertrouwen."], ["Het stelt zelf de definitieve woningwaarde vast", "De taxateur stelt de waarde vast; het instituut controleert het rapport."], ["Het bepaalt de hoogte van de hypotheekrente", "De rente wordt door de geldverstrekker bepaald, niet door een validatie-instituut."], ["Het voert een bouwkundige keuring van de woning uit en rapporteert de gebreken", "Validatie is een controle op het taxatierapport, geen bouwkundig onderzoek."]], "1b.3"],
["Noor (34) en Jesse (35) kopen een jarendertigwoning in Haarlem voor € 300.000. Zij willen direct € 40.000 verbouwen: een nieuwe keuken, een dakkapel en een tweede badkamer. De taxateur stelt de marktwaarde na verbouwing vast op € 350.000. Zij vragen welke waarde de bank gebruikt voor hun maximale hypotheek. Op welke waarde wordt de LTV-toets gebaseerd?", [["Op de marktwaarde na verbouwing van € 350.000, zoals de taxateur die heeft vastgesteld", "Bij financiering van een verbouwing mag de getaxeerde marktwaarde na verbouwing als woningwaarde worden gebruikt."], ["Op de koopsom van € 300.000, omdat de verbouwing op het moment van aankoop nog moet plaatsvinden", "De koopsom zonder verbouwing doet geen recht aan de waarde die met de verbouwing ontstaat."], ["Op de koopsom plus de verbouwingskosten, samen € 340.000", "De LTV gaat uit van de getaxeerde marktwaarde, niet van de optelsom van kosten."], ["Op de WOZ-waarde van de woning van vóór de verbouwing", "De WOZ-waarde is niet de maatstaf voor de LTV bij deze financiering."]], "1a.2"],
["Waarom moet een taxateur onafhankelijk zijn van de transactie die hij taxeert?", [["Om te voorkomen dat belangen bij verkoop of financiering de waardebepaling beïnvloeden", "De geldverstrekker baseert de lening op de waarde; die moet objectief zijn vastgesteld."], ["Omdat de taxateur anders geen overdrachtsbelasting over de koopsom van de woning mag berekenen", "Taxateurs berekenen geen overdrachtsbelasting; dat doet de notaris bij de aangifte."], ["Omdat de taxateur de koopovereenkomst moet ondertekenen", "De taxateur is geen partij bij de koopovereenkomst."], ["Omdat alleen een onafhankelijke taxateur het energielabel van de woning mag registreren", "Een energielabel wordt door een erkend energieadviseur geregistreerd, los van de taxatie."]], "1b.3"],
["Een klant denkt dat een taxatierapport ook uitsluitsel geeft over verborgen gebreken aan de woning. Wat is juist?", [["Een taxatie is geen bouwkundige keuring; voor de bouwkundige staat is apart onderzoek nodig", "De taxateur beoordeelt de waarde en zichtbare staat op hoofdlijnen, maar doet geen diepgaand bouwkundig onderzoek."], ["Een gevalideerd taxatierapport garandeert dat er geen gebreken zijn", "Validatie gaat over de kwaliteit van het rapport, niet over de afwezigheid van gebreken."], ["De taxateur is aansprakelijk voor alle later ontdekte gebreken", "De taxateur staat niet in voor gebreken die bij een taxatie redelijkerwijs niet zichtbaar zijn."], ["De geldverstrekker vergoedt de herstelkosten als de taxateur bij de taxatie gebreken heeft gemist", "De geldverstrekker geeft geen garantie op de bouwkundige staat van de woning."]], "1b.3"],
["Hoe komt een hypotheekrecht op een woning tot stand?", [["Door een notariële akte die wordt ingeschreven in de openbare registers (Kadaster)", "Voor vestiging van hypotheek op een registergoed zijn een notariële akte en inschrijving in de openbare registers vereist."], ["Door ondertekening van het bindend aanbod van de geldverstrekker door de klant en eventuele partner", "Het aanbod leidt tot een kredietovereenkomst, maar vestigt nog geen hypotheekrecht."], ["Door registratie van de lening bij het BKR", "Het BKR registreert kredieten, maar vestigt geen zakelijk recht."], ["Door een onderhandse akte tussen klant en geldverstrekker, gewaarmerkt door het Kadaster", "Een onderhandse akte is onvoldoende, ook niet met een waarmerk; een notariële akte is verplicht."]], "1f.3"],
["Wat houdt het recht van parate executie van de hypotheekhouder in?", [["Hij mag het onderpand bij wanprestatie zelf laten verkopen zonder voorafgaand rechterlijk vonnis", "Parate executie geeft de hypotheekhouder het recht de woning via een openbare veiling bij de notaris te verkopen."], ["Hij mag de woning zelf gaan bewonen of verhuren totdat de volledige achterstand is ingelopen", "Het hypotheekrecht geeft geen recht om de woning zelf te bewonen."], ["Hij mag de rente eenzijdig verhogen bij een betalingsachterstand", "Parate executie gaat over verkoop van het onderpand, niet over rentewijzigingen."], ["Hij moet altijd eerst toestemming van de AFM vragen voordat hij het onderpand openbaar laat veilen", "De AFM speelt geen rol bij de executie van een onderpand."]], "1f.3"],
["Een hypotheekhouder wil een executiewoning niet veilen maar onderhands verkopen. Wat is daarvoor nodig?", [["Toestemming van de voorzieningenrechter voor de onderhandse verkoop", "Onderhandse executoriale verkoop is mogelijk als de voorzieningenrechter de koopovereenkomst goedkeurt."], ["Alleen een nieuwe taxatie door een erkend taxateur", "Een taxatie is nuttig, maar vervangt de rechterlijke toestemming niet."], ["Toestemming van de Stichting WEW, ook als de lening zonder NHG is verstrekt", "Zonder NHG heeft de Stichting WEW geen rol, en toestemming van de rechter blijft nodig."], ["Een besluit van de algemene ledenvergadering van de VvE van het appartementencomplex", "De VvE beslist niet over de executie van een appartementsrecht."]], "1f.3"],
["Op een woning rusten twee hypotheekrechten van verschillende geldverstrekkers. Wat bepaalt in beginsel welke hypotheek voorrang heeft bij executie?", [["Het tijdstip van inschrijving in de openbare registers", "De rangorde van hypotheken volgt in beginsel de volgorde van inschrijving; de eerste inschrijving heeft voorrang."], ["De hoogte van het geleende bedrag per hypotheekrecht", "Een hogere lening geeft geen hogere rang."], ["De hoogte van de rente en de looptijd van elke lening", "Rentehoogte speelt geen rol bij de rangorde."], ["De datum van de koopovereenkomst bij de notaris", "De koopovereenkomst bepaalt de rang van hypotheken niet."]], "1f.3"],
["Wat is kenmerkend voor een bankhypotheek?", [["Het dekt ook toekomstige schulden, tot het ingeschreven bedrag", "Daardoor kan binnen de inschrijving later worden bijgeleend zonder nieuwe hypotheekakte."], ["Het dekt uitsluitend de oorspronkelijke lening", "Dat beschrijft een vaste (gewone) hypotheek, niet een bankhypotheek."], ["Het kan alleen worden gevestigd door een bank, niet door een verzekeraar", "De term gaat over de reikwijdte van de zekerheid, niet over het soort geldverstrekker."], ["Het vervalt na het einde van de rentevaste periode", "Een hypotheekrecht vervalt niet door het einde van een rentevaste periode."]], "1e.4"],
["Wim (52) kocht zijn woning in Deventer lang voor zijn huwelijk en staat als enige eigenaar in het Kadaster. Hij is getrouwd met Ingrid, die sinds hun trouwen bij hem in de woning woont. Wim wil een extra hypotheek op de woning nemen om een camper te kopen. Hij vindt dat Ingrid daar niets mee te maken heeft, omdat het zijn huis is. Wat is juist?", [["Hij heeft toestemming van Ingrid nodig, omdat zij woont in de woning die hij met hypotheek wil bezwaren", "Voor het bezwaren van een woning die door echtgenoten wordt bewoond, is toestemming van de andere echtgenoot nodig, ook als die geen eigenaar is."], ["Hij heeft geen toestemming nodig, omdat hij de enige eigenaar van de woning is", "De wet beschermt de echtgenoot die in de woning woont, ongeacht wie eigenaar is."], ["Hij heeft voor elke hypotheek op de woning toestemming van de kantonrechter nodig", "De rechter komt alleen in beeld als de echtgenoot toestemming zonder goede reden weigert."], ["Alleen als zij met huwelijkse voorwaarden zijn getrouwd, is voor de hypotheek toestemming van Ingrid nodig", "De toestemmingseis geldt ongeacht het huwelijksvermogensregime."]], "1a.4"],
["Wat is erfpacht volgens Boek 5 BW?", [["Een zakelijk recht om andermans onroerende zaak te gebruiken, tegen canon", "De erfpachter heeft een zelfstandig zakelijk recht op de grond van de eigenaar en betaalt daarvoor doorgaans een canon."], ["Een huurovereenkomst voor grond die jaarlijks opzegbaar is", "Erfpacht is een zakelijk recht en geen huur, en is niet zomaar jaarlijks opzegbaar."], ["Een hypotheekrecht ten gunste van de gemeente", "Erfpacht is een gebruiksrecht, geen zekerheidsrecht."], ["Het recht om eigen gebouwen in, op of boven andermans grond te hebben", "Dat is het opstalrecht, een ander zakelijk recht uit Boek 5 BW."]], "1a.4"],
["Wat is een belangrijk nadeel van een variabele hypotheekrente voor de consument?", [["De maandlasten kunnen bij een rentestijging direct oplopen", "Bij variabele rente draagt de consument het renterisico; stijgt de marktrente, dan stijgen de lasten."], ["Extra aflossen is bij variabele rente nooit toegestaan", "Juist bij variabele rente is boetevrij aflossen doorgaans ruim mogelijk."], ["De rente is bij variabel altijd hoger dan bij een lange rentevaste periode", "Dat hangt af van de rentestructuur; variabel is vaak juist lager."], ["Variabele rente is fiscaal niet aftrekbaar", "De aftrekbaarheid hangt niet af van de rentevorm."]], "1e.2"],
["Wat is een plafondrente?", [["Een variabele rente die niet boven een afgesproken maximum kan stijgen", "De klant profiteert van rentedalingen, terwijl het plafond het risico op stijging begrenst."], ["Een vaste rente die na tien jaar automatisch daalt naar het marktniveau", "Een plafondrente is variabel met een maximum, geen vaste rente met een daling."], ["De maximale rente die de AFM jaarlijks voor alle hypotheken vaststelt", "De AFM stelt geen maximumrente voor hypotheken vast; het plafond is een productafspraak."], ["Een rente die gelijk is aan de wettelijke rente", "De wettelijke rente geldt bij betalingsachterstanden en staat los van de plafondrente."]], "1e.2"],
["Tussen het uitbrengen van de offerte en het passeren van de akte daalt de hypotheekrente. Welke productvoorwaarde zorgt ervoor dat de klant van die daling profiteert?", [["Een rentedaalgarantie (rentepluk)", "Daarmee krijgt de klant bij passeren de laagste rente uit de periode tussen offerte en passeren."], ["Rentemiddeling bij oversluiten", "Rentemiddeling betreft het verwerken van een boete bij tussentijds oversluiten in een nieuwe rente."], ["Een plafondrente op de lening", "Een plafond begrenst een variabele rente naar boven, maar geeft geen recht op een lagere offerterente."], ["Een verlengde rentevaste periode", "Een langere rentevaste periode verandert niets aan rentedalingen in de offerteperiode."]], "1h.6"],
["Veel geldverstrekkers werken met risico-opslagen per LTV-klasse. Wat kan een klant doen als zijn woning flink in waarde stijgt?", [["Een nieuwe waardering laten doen voor een mogelijk lagere risico-opslag", "Een lagere LTV betekent minder risico voor de geldverstrekker; afhankelijk van de voorwaarden kan de opslag dalen."], ["Een hogere renteaftrek aanvragen bij de Belastingdienst", "De woningwaarde heeft geen invloed op de hoogte van de aftrekbare rente."], ["Zijn rentevaste periode kosteloos laten verlengen tot dertig jaar tegen dezelfde rente", "Een waardestijging geeft geen recht op kosteloze verlenging van de rentevaste periode tegen dezelfde rente."], ["De NHG-borgtocht laten verhogen tot de nieuwe waarde", "De NHG-borgtocht volgt een vast afbouwschema en wordt niet verhoogd bij waardestijging."]], "1h.6"],
["Een klant met een krap budget wil zekerheid over zijn maandlasten. Waarom past een lange rentevaste periode vaak bij hem?", [["Omdat zijn lasten langdurig vaststaan en hij minder kwetsbaar is voor rentestijgingen", "Een lange rentevaste periode beperkt het renterisico, wat belangrijk is als een lastenstijging niet kan worden opgevangen."], ["Omdat de rente bij een lange rentevaste periode altijd het laagst is van alle looptijden", "Een langere rentevaste periode heeft vaak juist een hogere rente; het voordeel is zekerheid."], ["Omdat hij dan nooit een vergoeding bij vervroegde aflossing hoeft te betalen, ook niet bij verhuizing", "Ook bij een lange rentevaste periode kan bij extra aflossing boven de boetevrije ruimte een vergoeding verschuldigd zijn."], ["Omdat hij dan geen kredietwaardigheidstoets hoeft te ondergaan", "De toets geldt altijd; alleen de toetsrente kan verschillen."]], "1d.2"],
["Wat is volgens de Wft de maximale vergoeding die een kredietgever mag vragen bij vervroegde aflossing van een hypotheek?", [["Niet meer dan het financiële nadeel dat de kredietgever door de vervroegde aflossing lijdt", "De vergoeding is een compensatie voor renteverlies en mag het werkelijke nadeel niet overstijgen."], ["Een vast percentage van de oorspronkelijke hoofdsom, ongeacht de marktrente en de resterende rentevaste periode", "Een vast percentage los van het werkelijke nadeel is niet toegestaan."], ["De volledige rente over de resterende looptijd van de lening", "Dat zou veel hoger zijn dan het werkelijke nadeel."], ["Het bedrag dat de klant met de oversluiting bespaart", "De besparing van de klant is niet de maatstaf; het gaat om het nadeel van de kredietgever."]], "1e.10"],
["Lotte (45) heeft een erfenis ontvangen en wil haar hypotheek van € 150.000 in één keer aflossen. Haar rente van 2,5% staat nog zes jaar vast. De rente die haar geldverstrekker nu rekent voor een vergelijkbare rentevaste periode is 3,8%. Zij is bang voor een hoge boete. Wat is in beginsel juist?", [["Geen vergoeding, omdat de geldverstrekker bij een hogere marktrente geen renteverlies lijdt", "De vergoeding mag niet hoger zijn dan het financiële nadeel; als de geldverstrekker het geld duurder kan uitlenen, is er geen nadeel."], ["Zij betaalt een vergoeding, omdat zij binnen de rentevaste periode volledig aflost", "Aflossen binnen de rentevaste periode leidt alleen tot een vergoeding als de geldverstrekker renteverlies lijdt."], ["De geldverstrekker moet haar een vergoeding betalen voor het renteverschil", "Een vergoeding van de geldverstrekker aan de klant is in dit geval niet gebruikelijk of verplicht."], ["Volledig aflossen is niet toegestaan zolang de huidige marktrente hoger ligt dan haar contractrente", "Vervroegd aflossen is altijd toegestaan; de vraag is alleen of een vergoeding verschuldigd is."]], "1e.10"],
["Van welke factoren hangt de hoogte van de vergoeding bij vervroegde aflossing vooral af?", [["Het renteverschil, de resterende rentevaste periode en het bedrag boven de boetevrije ruimte", "Hoe groter het renteverschil, hoe langer de resterende periode en hoe hoger het boeteplichtige bedrag, des te hoger de vergoeding."], ["De WOZ-waarde van de woning, het energielabel en de leeftijd van de klant bij het oversluiten", "Deze factoren bepalen de vergoeding niet."], ["Het inkomen van de klant, de woningwaarde en het aantal al betaalde maandtermijnen", "Inkomen speelt geen rol, en het gaat om de resterende rentevaste periode in plaats van de betaalde termijnen."], ["De hoogte van de oorspronkelijke advieskosten en notariskosten", "Afsluitkosten van destijds zijn niet bepalend voor de vergoeding."]], "1e.10"],
["Gerard (50) en Ria (49) hebben een hypotheek van € 230.000 bij een bank in hun woonplaats Tilburg. Hun rentevaste periode van tien jaar loopt over twee maanden af. Een andere geldverstrekker biedt hun een lagere rente aan. Zij willen op de renteherzieningsdatum volledig oversluiten. Wat geldt voor een vergoeding wegens vervroegde aflossing?", [["Op de renteherzieningsdatum is geen vergoeding verschuldigd, omdat de rentevaste periode dan afloopt", "Op de renteherzieningsdatum lijdt de geldverstrekker geen renteverlies, dus is aflossen boetevrij."], ["Zij betalen een vergoeding over de volgende rentevaste periode die de huidige bank hun heeft aangeboden", "Een nieuwe rentevaste periode is nog niet afgesproken, dus is er geen renteverlies."], ["Zij betalen altijd een vaste vergoeding van één maand rente over de hoofdsom", "Een vaste vergoeding van één maand rente is geen regel; de vergoeding moet aansluiten bij het werkelijke nadeel."], ["Boetevrij oversluiten kan pas als de volledige looptijd van 30 jaar is verstreken", "De renteherzieningsdatum is juist het moment waarop boetevrij kan worden afgelost."]], "1e.10"],
["Een klant sluit zijn eigenwoningschuld over naar een lagere rente en betaalt daarbij een vergoeding wegens vervroegde aflossing. Hoe wordt die vergoeding fiscaal behandeld?", [["Als aftrekbare kosten van de eigenwoningschuld", "Een boete bij oversluiten van een eigenwoningschuld is aftrekbaar als financieringskosten."], ["Als niet-aftrekbare verwervingskost van de woning", "De vergoeding hangt samen met de financiering, niet met de verwerving van de woning."], ["Als schuld in box 3", "De vergoeding is een kostenpost, geen schuld; zij is aftrekbaar in box 1."], ["Als inkomen dat bij de geldverstrekker belastingvrij is", "Wat de geldverstrekker met de vergoeding doet, bepaalt de fiscale positie van de klant niet."]], "1e.7"],
["Wat is het ESIS bij hypothecair krediet?", [["Een Europees standaardinformatieblad over het aangeboden krediet", "Het ESIS komt voort uit de hypothekenrichtlijn en maakt aanbiedingen vergelijkbaar door een vaste opbouw."], ["Een Europees register van hypotheken met betalingsachterstanden bij consumenten", "Het ESIS is geen register; registratie van achterstanden gebeurt in Nederland bij het BKR."], ["Een fiscaal formulier voor de aangifte van hypotheekrente", "Het ESIS is precontractuele informatie, geen belastingformulier."], ["Een certificaat waarmee de adviseur zijn vakbekwaamheid aantoont", "Vakbekwaamheid blijkt uit Wft-diploma's en PE, niet uit het ESIS."]], "1a.6"],
["Wanneer moet de consument het ESIS uiterlijk ontvangen?", [["Tijdig voordat hij gebonden is aan een kredietovereenkomst of aanbod", "De consument moet de informatie kunnen vergelijken en overwegen voordat hij zich bindt."], ["Pas na het passeren van de hypotheekakte", "Na het passeren is het te laat om de informatie te gebruiken bij de keuze."], ["Binnen een jaar na het afsluiten, bij de eerste jaaropgave van de geldverstrekker", "Het ESIS is precontractueel en hoort vóór de binding te worden verstrekt."], ["Alleen als de consument er uitdrukkelijk om vraagt", "Verstrekking is een verplichting voor de aanbieder, niet afhankelijk van een verzoek."]], "1a.6"],
["Wat drukt het jaarlijks kostenpercentage (JKP) uit dat in het ESIS staat?", [["De totale kosten van het krediet als percentage per jaar", "Het JKP omvat rente en bijkomende kosten, zodat aanbiedingen beter vergelijkbaar zijn."], ["Alleen de nominale debetrente op jaarbasis", "Het JKP omvat meer dan de rente, zoals verplichte bijkomende kosten."], ["Het percentage van het inkomen dat aan woonlasten opgaat", "Dat is de financieringslast, geen JKP."], ["Het deel van de woningwaarde dat wordt gefinancierd", "Dat is de LTV, geen kostenpercentage."]], "1e.1"],
["Welke informatie hoort onder meer in het ESIS te staan?", [["De voorwaarden en mogelijke kosten van vervroegde aflossing", "Het ESIS bevat een vast onderdeel over het recht op vervroegde aflossing en de vergoeding die daarbij kan gelden."], ["Het advies van de adviseur over de best passende verzekering", "Het ESIS beschrijft het krediet; het advies wordt apart vastgelegd."], ["De WOZ-beschikking van de gemeente", "De WOZ-beschikking is geen onderdeel van het ESIS."], ["De uitkomst van de BKR-toets van de partner", "Persoonlijke toetsingsresultaten zijn geen standaardonderdeel van het ESIS."]], "1a.6"],
["Sophie (27) werkt sinds negen maanden als laborante bij een ziekenhuis in Leiden, met een jaarcontract. Zij verdient € 40.000 bruto per jaar inclusief vakantiegeld. Zij wil samen met haar vriend een woning kopen. Haar leidinggevende is tevreden en verwacht haar contract om te zetten in een vast contract. Welke verklaring van de werkgever maakt het voor geldverstrekkers doorgaans mogelijk haar inkomen volledig mee te nemen?", [["Een werkgeversverklaring waarin de werkgever de intentie uitspreekt haar een vast contract te geven", "Met een intentieverklaring voor een vast dienstverband nemen geldverstrekkers een tijdelijk inkomen doorgaans mee als vast inkomen."], ["Een verklaring dat zij goed functioneert en haar proeftijd bij het ziekenhuis met succes heeft doorlopen", "Goed functioneren zegt niets over de voortzetting van het dienstverband na afloop van het contract."], ["Een recente salarisstrook waaruit blijkt dat zij al negen maanden in dienst is", "Een salarisstrook toont het inkomen, niet of het contract wordt voortgezet."], ["Een verklaring van haar vakbond over de lonen in de cao voor ziekenhuizen", "Een cao-overzicht zegt niets over haar persoonlijke dienstverband."]], "2c.2"],
["Wat is een perspectiefverklaring?", [["Een verklaring over het arbeidsmarktperspectief van een flexwerker", "Een perspectiefverklaring kan het mogelijk maken een hypotheek te verkrijgen als er geen intentieverklaring van de werkgever is."], ["Een verklaring van de geldverstrekker over de verwachte renteontwikkeling", "De perspectiefverklaring gaat over het inkomen van de klant, niet over de rente."], ["Een verklaring van de taxateur over de verwachte waardestijging", "Waardeverwachtingen zijn geen basis voor deze verklaring en ook niet voor de kredietwaardigheidstoets."], ["Een verklaring van het UWV over een lopende WW-uitkering", "Een WW-uitkering is geen arbeidsmarktperspectief en het UWV geeft deze verklaring niet af."]], "2c.2"],
["Wat is Inkomensbepaling Loondienst (IBL)?", [["Een methode om het toetsinkomen te bepalen met UWV-gegevens", "IBL gebruikt het verzekeringsbericht van het UWV om het inkomen over de afgelopen periode vast te stellen."], ["Een fiscale regeling om hypotheekrente via de loonheffing te verrekenen", "Dat is de voorlopige aanslag of teruggaaf, geen inkomensbepaling voor de hypotheek."], ["Een verplichte verzekering tegen inkomensverlies bij werkloosheid", "IBL is geen verzekering, maar een rekenmethode voor het inkomen."], ["Een inkomensverklaring voor zelfstandig ondernemers", "IBL is bedoeld voor werknemers in loondienst; voor ondernemers gelden andere methoden."]], "1i.4"],
["Een zelfstandig ondernemer vraagt een hypotheek aan. Hoe wordt zijn inkomen doorgaans vastgesteld?", [["Op basis van cijfers over meerdere jaren of een inkomensverklaring", "Bij ondernemers wordt gekeken naar de resultaten over meerdere jaren, omdat het inkomen kan schommelen."], ["Alleen op basis van de omzet van de laatste maand", "Eén maand omzet zegt weinig over het duurzame inkomen."], ["Op basis van een werkgeversverklaring die hij zelf ondertekent", "Een ondernemer kan geen werkgeversverklaring over zichzelf afgeven als bewijs van inkomen."], ["Op basis van het verwachte inkomen uit zijn ondernemingsplan", "Verwachtingen zonder historie zijn doorgaans onvoldoende om verantwoord krediet te verstrekken."]], "2c.2"],
["Erik (47) is na zijn scheiding op zoek naar een eigen appartement in Utrecht. Hij verdient € 70.000 bruto per jaar als projectleider. Hij betaalt maandelijks partneralimentatie aan zijn ex-vrouw en kinderalimentatie voor zijn twee kinderen. Hij vraagt zich af hoeveel hij nog kan lenen. Hoe telt de partneralimentatie mee bij de bepaling van zijn maximale hypotheek?", [["Betaalde partneralimentatie verlaagt zijn toetsinkomen, omdat het een vaste verplichting is", "De TRHK brengt betaalde partneralimentatie in mindering op het toetsinkomen."], ["De partneralimentatie verhoogt zijn toetsinkomen, omdat hij die fiscaal mag aftrekken", "Aftrekbaarheid maakt de alimentatie niet tot extra inkomen; het blijft een last."], ["De partneralimentatie speelt geen rol, omdat alleen zijn brutosalaris bij de leennormen telt", "Alimentatie drukt op de betaalcapaciteit en wordt dus meegenomen."], ["De partneralimentatie verlaagt de woningwaarde die voor de LTV wordt gebruikt", "Alimentatie heeft geen relatie met de woningwaarde."]], "1i.4"],
["Een klant koopt een appartement in een gebouw met een Vereniging van Eigenaars (VvE). Hoe is de verzekering van gebouw en inboedel doorgaans geregeld?", [["De VvE verzekert het gebouw met een opstalverzekering; de eigenaar verzekert zelf zijn inboedel", "Het gebouw wordt collectief door de VvE verzekerd; de inboedel en eventuele eigen verbeteringen regelt de bewoner zelf."], ["Iedere eigenaar sluit een eigen opstalverzekering af voor zijn deel van het gebouw", "Bij appartementsrechten regelt de VvE de opstalverzekering voor het hele gebouw."], ["De VvE verzekert zowel het gebouw als de inboedel van alle bewoners", "De inboedel valt buiten de VvE-polis; die moet iedere bewoner zelf verzekeren."], ["Een appartement hoeft hij niet zelf te verzekeren, omdat de geldverstrekker het risico op schade draagt", "De geldverstrekker eist juist dat het onderpand goed verzekerd is; via de VvE is dat geregeld."]], "1e.5"],
["Bij een BKR-toetsing blijkt dat een klant een doorlopend krediet heeft. Wat doet de kredietgever daarmee?", [["Hij neemt de last van het krediet mee als financiële verplichting", "Lopende kredieten drukken op de betaalcapaciteit en verlagen daardoor de maximale hypotheek."], ["Hij negeert het krediet zolang er geen achterstand bij het BKR is geregistreerd", "Ook zonder achterstand is het krediet een verplichting die meeweegt."], ["Hij verhoogt het toetsinkomen met de kredietlimiet", "Een kredietlimiet is geen inkomen."], ["Hij moet de aanvraag altijd afwijzen", "Een lopend krediet is geen automatische afwijzingsgrond."]], "1e.6"],
["Welk inkomensbestanddeel telt bij een werknemer in loondienst in beginsel mee in het bruto toetsinkomen?", [["Het vakantiegeld dat hij jaarlijks ontvangt", "Het toetsinkomen is het bruto jaarinkomen inclusief vaste componenten zoals vakantietoeslag."], ["Een eenmalige bonus zonder structureel karakter", "Incidentele beloningen zijn niet duurzaam en tellen in beginsel niet mee."], ["De verwachte loonsverhoging over drie jaar", "Toekomstige verhogingen zijn onzeker en tellen niet mee als inkomen."], ["De teruggave van hypotheekrenteaftrek", "Het fiscale voordeel zit al in de financieringslastpercentages en wordt niet bij het inkomen opgeteld."]], "2c.2"],
["Een stel koopt een woning; alleen partner A heeft inkomen. Wat is het belangrijkste doel van een overlijdensrisicoverzekering in het advies?", [["Zorgen dat de partner na overlijden van A de lasten kan dragen", "De dekking wordt zo bepaald dat de schuld na overlijden zo ver daalt dat de lasten bij het inkomen van de nabestaande passen."], ["Zorgen dat de hypotheekrente na overlijden aftrekbaar blijft", "De renteaftrek hangt niet af van een overlijdensrisicoverzekering."], ["De NHG-kostengrens verhogen", "Een verzekering heeft geen invloed op de NHG-kostengrens."], ["Voldoen aan de fiscale aflossingseis voor de lening", "De aflossingseis heeft betrekking op de lening, niet op een verzekering."]], "1i.6"],
["Een werknemer in loondienst wordt langdurig ziek. Hoe verloopt zijn inkomen in hoofdlijnen?", [["Twee jaar loondoorbetaling, daarna mogelijk een lagere WIA-uitkering", "Na de loondoorbetalingsperiode kan het inkomen sterk dalen; dat moet in het hypotheekadvies worden doorgerekend."], ["Hij houdt tot zijn pensioen zijn volledige salaris via de werkgever", "De loondoorbetaling bij ziekte is beperkt tot twee jaar."], ["Hij krijgt direct een WW-uitkering van het UWV", "WW is voor werkloosheid, niet voor ziekte bij een lopend dienstverband."], ["De NHG neemt de maandlasten over vanaf de eerste ziektedag", "NHG betaalt geen maandlasten; zij kan alleen bij gedwongen verkoop een rol spelen."]], "1a.4"],
["Kevin (34) werkt al vijf jaar als zelfstandig timmerman en maakt gemiddeld € 50.000 winst per jaar. Hij koopt met zijn partner Iris, die parttime in loondienst werkt, een woning in Amersfoort. Hij heeft geen arbeidsongeschiktheidsverzekering en vindt de premie te duur. Iris vraagt wat er gebeurt als hij door een ongeluk niet meer kan werken. Wat is in het advies over arbeidsongeschiktheid een bijzonder aandachtspunt?", [["Kevin heeft als zelfstandige geen WIA-dekking en moet zelf een voorziening treffen", "Zelfstandigen vallen niet onder de WIA; zonder eigen verzekering of buffer valt zijn inkomen bij arbeidsongeschiktheid grotendeels weg."], ["Kevin krijgt via zijn opdrachtgevers twee jaar lang zijn inkomen doorbetaald", "Loondoorbetaling bij ziekte geldt voor werknemers, niet voor zelfstandigen."], ["Kevin is via de NHG-borgtocht op de hypotheek automatisch verzekerd tegen arbeidsongeschiktheid", "NHG is geen arbeidsongeschiktheidsverzekering en vult geen inkomen aan."], ["Bij arbeidsongeschiktheid scheldt de geldverstrekker de hypotheek van Kevin kwijt", "De schuld blijft bestaan; kwijtschelding bij arbeidsongeschiktheid bestaat niet."]], "1i.6"],
["Waarvan hangt de duur van een WW-uitkering in hoofdlijnen af?", [["Van het arbeidsverleden van de werknemer", "Hoe langer iemand heeft gewerkt, hoe langer de WW-uitkering kan duren, tot een wettelijk maximum."], ["Van de hoogte van de hypotheek", "De hypotheek heeft geen invloed op de WW-duur."], ["Van de leeftijd van de partner", "De WW is een individuele werknemersverzekering, los van de partner."], ["Van de rentevaste periode van de lening", "De rentevaste periode speelt geen rol bij de WW."]], "1a.4"],
["Marloes (38) en Dennis (40) kochten zes jaar geleden samen een woning in Zoetermeer en sloten samen de hypotheek af. Zij gaan uit elkaar; Marloes blijft met de kinderen in de woning wonen. Dennis spreekt met haar af dat zij voortaan alle lasten betaalt en dat hij daarmee van de schuld af is. Hij vraagt of hij tegenover de bank nog ergens voor aansprakelijk is. Wat geldt?", [["Beiden blijven hoofdelijk aansprakelijk voor de hele schuld tot de geldverstrekker Dennis ontslaat", "De geldverstrekker kan het volledige bedrag van ieder van hen vorderen; hun onderlinge afspraken binden de bank niet."], ["Dennis is door de onderlinge afspraak met Marloes automatisch niet meer aansprakelijk tegenover de bank", "Een afspraak tussen de partners werkt alleen tussen hen; voor ontslag uit de hoofdelijke aansprakelijkheid is de geldverstrekker nodig."], ["Ieder is tegenover de bank alleen aansprakelijk voor de helft van de schuld", "Onderling kunnen zij de schuld verdelen, maar tegenover de geldverstrekker zijn zij hoofdelijk aansprakelijk."], ["De hypotheek vervalt bij het einde van de relatie en Marloes moet een nieuwe afsluiten", "Een relatie-einde laat de bestaande kredietovereenkomst intact."]], "1f.4"],
["Ad (58) is vrachtwagenchauffeur en wil met zijn vrouw Thea (57) verhuizen naar een gelijkvloerse woning in Veenendaal. Zij hebben een hypotheek nodig van € 180.000 met een looptijd van dertig jaar. Over ongeveer negen jaar bereikt Ad de AOW-leeftijd en daalt zijn inkomen. Thea werkt niet en heeft geen eigen pensioen opgebouwd. Wat moet de adviseur in elk geval in kaart brengen?", [["Of de lasten na pensionering te dragen zijn met hun verwachte AOW- en pensioeninkomen", "Bij een looptijd tot na de AOW-leeftijd moet de betaalbaarheid ook voor de periode na pensionering worden beoordeeld."], ["Of zij met de overwaarde van hun woning vóór het pensioen een tweede woning kunnen kopen", "Een tweede woning is hier geen relevant aandachtspunt; het gaat om de betaalbaarheid na pensionering."], ["Of de hypotheekrente na het bereiken van de AOW-leeftijd automatisch daalt", "De rente hangt niet af van de leeftijd van de klant."], ["Of de Wet Hillen de hypotheekrente na pensionering geheel of gedeeltelijk overneemt", "De Wet Hillen gaat over een aftrek bij geen of geringe eigenwoningschuld en betaalt geen rente."]], "1h.1"],
["Hoe hoort de adviseur risico's zoals overlijden, arbeidsongeschiktheid en werkloosheid in het hypotheekadvies te behandelen?", [["De gevolgen doorrekenen, bespreken en de keuze van de klant vastleggen", "Een passend advies laat zien wat er gebeurt en welke oplossingen er zijn; de klant kiest bewust en dat wordt vastgelegd."], ["Alleen benoemen als de klant er zelf naar vraagt", "Een adviseur moet risico's uit zichzelf onderzoeken en bespreken."], ["Altijd voor elk risico een verzekering verplicht stellen", "Een verzekering is niet altijd nodig; een buffer of acceptatie kan ook passen."], ["Overlaten aan de geldverstrekker, omdat die de kredietwaardigheid toetst", "De kredietwaardigheidstoets vervangt de risicoanalyse van de adviseur niet."]], "2d.2"],
["Welke invloed heeft een gunstig energielabel van de woning op de leencapaciteit volgens de TRHK?", [["Afhankelijk van het label is extra leenruimte mogelijk", "De TRHK geeft extra leenruimte bij zuinigere woningen, omdat de energielasten daar lager zijn."], ["Een gunstig label verhoogt de maximale LTV naar 125%", "Het energielabel verhoogt de LTV niet tot zo'n niveau."], ["Het energielabel heeft geen invloed op de leennormen", "De TRHK houdt wel degelijk rekening met het energielabel."], ["Bij een gunstig label vervalt de toetsrente", "Het label raakt het leenbedrag, niet de toetsrentesystematiek."]], "1a.2"],
["Een klant wil energiebesparende voorzieningen, zoals zonnepanelen en isolatie, meefinancieren. Wat is volgens de leennormen mogelijk?", [["Onder voorwaarden een hypotheek boven 100% van de marktwaarde voor die voorzieningen", "Energiebesparende voorzieningen vormen een uitzondering op de hoofdregel van een LTV van maximaal 100%."], ["Alleen als de voorzieningen al vóór de aankoop zijn aangebracht en in de taxatie zijn meegenomen", "Ook nog aan te brengen voorzieningen kunnen worden meegefinancierd, vaak via een bouwdepot."], ["Nooit, omdat de LTV zonder uitzonderingen 100% is", "De TRHK kent juist voor energiebesparende voorzieningen een uitzondering."], ["Alleen via een persoonlijke lening buiten de hypotheek", "Meefinancieren binnen de hypotheek is juist mogelijk."]], "1a.2"],
["Bij de toetsing van een hypotheekaanvraag blijkt uit het BKR dat de klant een paar jaar geleden een betalingsachterstand op een creditcard had, die is geregistreerd. Wat is juist?", [["De kredietgever weegt de registratie mee in zijn beoordeling, wat tot afwijzing kan leiden", "Een achterstandsregistratie zegt iets over het betaalgedrag; de kredietgever beoordeelt zelf of verstrekken verantwoord is."], ["Het BKR beslist zelf of de klant de hypotheek mag krijgen", "Het BKR registreert alleen gegevens; het neemt geen kredietbeslissingen."], ["De registratie verdwijnt automatisch zodra de klant bij een geldverstrekker een hypotheek aanvraagt", "Een aanvraag heeft geen invloed op het bestaan of de bewaartermijn van een registratie."], ["Alleen achterstanden op een eerdere hypotheek mogen worden meegewogen", "Ook achterstanden op andere kredieten zeggen iets over het betaalgedrag en worden meegewogen."]], "1e.6"],
["Een klant financiert de verduurzaming via de hypotheek en het bedrag wordt in een bouwdepot gestort. Wat is de functie van dat bouwdepot?", [["Uitbetaling volgt pas op facturen voor de afgesproken maatregelen", "Het depot borgt dat het geld voor de voorzieningen wordt gebruikt die de waarde of de energiezuinigheid verbeteren."], ["Het geld wordt direct op de privérekening van de klant gestort", "Juist dat voorkomt het bouwdepot."], ["Het geld wordt belegd tot de rentevaste periode eindigt", "Een bouwdepot is geen beleggingsrekening."], ["Het geld dient als buffer voor betalingsachterstanden", "Een bouwdepot is bestemd voor de verbouwing, niet voor achterstanden."]], "1e.3"],
["Wat regelt de hypothekenrichtlijn (MCD) over koppelverkoop?", [["Koppelverkoop is in beginsel verboden; gebundelde verkoop (los verkrijgbaar) is toegestaan", "Bij koppelverkoop is het krediet niet los verkrijgbaar; dat is verboden. Een bundel waarbij de onderdelen ook los te krijgen zijn, mag wel."], ["Koppelverkoop is altijd toegestaan als de consument vooraf een ESIS met alle productcombinaties heeft gekregen", "Een ESIS maakt verboden koppelverkoop niet toelaatbaar."], ["Elke combinatie van een hypotheek met een ander product is verboden", "Gebundelde verkoop is wel toegestaan."], ["Koppelverkoop is alleen verboden bij hypotheken met NHG", "Het verbod volgt uit de richtlijn en geldt niet alleen bij NHG."]], "1a.3"],
["Waarop mag de kredietwaardigheidsbeoordeling volgens de hypothekenrichtlijn niet hoofdzakelijk worden gebaseerd?", [["Op de verwachting dat de woningwaarde zal stijgen", "De toets moet vooral kijken naar het vermogen van de consument om aan zijn verplichtingen te voldoen, niet op verwachte waardestijging."], ["Op het actuele inkomen van de consument uit loondienst of onderneming", "Het inkomen is juist een kernonderdeel van de beoordeling."], ["Op de vaste lasten en de bestaande verplichtingen van de consument", "Vaste lasten horen bij een goede beoordeling van de betaalcapaciteit."], ["Op de informatie uit het BKR-register", "BKR-informatie is een belangrijke bron en wordt juist gebruikt."]], "1a.3"],
["Een klant sluit een hypotheek rechtstreeks af bij een bank, met advies van een adviseur in dienst van die bank. Wat geldt voor de kosten van dat advies?", [["De bank brengt de kosten voor advies en distributie apart in rekening, net als een tussenpersoon", "Door het provisieverbod en de regels over kostentransparantie mogen ook directe aanbieders deze kosten niet in de productprijs verstoppen."], ["De advieskosten zitten bij een bank altijd verwerkt in de hypotheekrente en zijn dus niet zichtbaar", "Kosten voor advies en distributie mogen niet in de rente worden verborgen; ze moeten apart zichtbaar zijn."], ["Advies door een bankmedewerker is gratis, omdat de bank geen provisie ontvangt", "Ook de bank mag kosten voor advies rekenen; het provisieverbod maakt die kosten juist zichtbaar."], ["De kosten zijn lager dan bij een tussenpersoon, omdat de wet dat voorschrijft", "De wet schrijft geen lagere kosten voor directe aanbieders voor; zij moeten de kosten wel apart en vooraf vermelden."]], "1e.8"],
["Mag een hypotheekadviseur een provisie ontvangen van de geldverstrekker voor de bemiddeling in een hypotheek voor een consument?", [["Nee, voor hypotheken geldt sinds 2013 een provisieverbod", "Sinds 2013 mag een adviseur geen provisie van de aanbieder ontvangen voor hypotheken voor consumenten."], ["Ja, mits de provisie in het ESIS wordt vermeld", "Vermelding maakt de provisie niet toegestaan."], ["Ja, als de provisie lager is dan 1% van de hoofdsom", "Er geldt geen drempel; provisie is verboden."], ["Alleen als de klant schriftelijk toestemming geeft", "Toestemming van de klant heft het verbod niet op."]], "1e.8"],
["Jasper (32) en Mirthe (31) hebben hun droomhuis in Rotterdam gevonden en willen het maximale bedrag lenen. Uit de inventarisatie blijkt dat zij daarna geen ruimte meer hebben om te sparen en geen buffer overhouden. Mirthe verwacht binnen twee jaar een kind en wil dan minder gaan werken. Zij zeggen dat zij die risico's voor lief nemen. Wat verwacht de zorgplicht van de adviseur?", [["Dat hij de risico's bespreekt, een passend advies geeft en het gesprek en hun keuze vastlegt", "De adviseur moet de klant passend adviseren, de risico's toelichten en vastleggen wat is besproken en besloten."], ["Dat hij hun wens zonder verdere bespreking uitvoert, omdat zij zelf verantwoordelijk zijn voor de keuze", "De zorgplicht vraagt een eigen, passend advies; de wens van de klant zonder meer uitvoeren is onvoldoende."], ["Dat hij hen naar een andere adviseur verwijst, omdat hij deze lening niet mag adviseren", "Doorverwijzen is niet nodig; hij moet zelf passend adviseren."], ["Dat hij de AFM vooraf om toestemming vraagt om boven zijn advies te mogen lenen", "De AFM geeft geen toestemming voor individuele adviezen."]], "2e.2"],
["Waarom benaderen geldverstrekkers klanten met een aflossingsvrije hypotheek actief?", [["Om hen te wijzen op het risico van een onbetaalbare schuld aan het einde", "De AFM heeft aanbieders gevraagd klanten tijdig te wijzen op dit risico, passend bij hun zorgplicht."], ["Om de aflossingsvrije lening verplicht om te zetten in een annuïteitenlening", "Een verplichte omzetting is geen gevolg van deze benadering."], ["Om het overgangsrecht van de klant in te trekken", "Een geldverstrekker kan het fiscale overgangsrecht niet intrekken."], ["Om de woning opnieuw te laten taxeren voor de WOZ-waarde", "De WOZ-waarde wordt door de gemeente vastgesteld."]], "3e.3"],
["Viktor (45) wil een appartement in Amsterdam kopen voor € 600.000 en brengt € 250.000 eigen geld in. Hij kan niet goed uitleggen waar dit geld vandaan komt; volgens hem is het gespaard via vrienden in het buitenland. Het bedrag staat pas sinds kort op zijn rekening, na meerdere contante stortingen. Zijn inkomen als zelfstandig consultant is bescheiden. Wat vraagt de Wwft van de geldverstrekker?", [["De herkomst van het geld onderzoeken en een ongebruikelijke transactie melden bij FIU-Nederland", "Bij een onduidelijke herkomst moet de instelling nader onderzoek doen en zo nodig een ongebruikelijke transactie melden."], ["Het geld accepteren, omdat eigen inbreng het kredietrisico van de bank juist verlaagt", "Een lager kredietrisico neemt de Wwft-plicht om de herkomst te onderzoeken niet weg."], ["De klant direct aangeven bij de politie en de aanvraag zonder uitleg afwijzen", "De Wwft vraagt een melding bij FIU-Nederland, geen aangifte bij de politie."], ["De klant vragen eerst een officiële verklaring van herkomst bij de AFM of de Belastingdienst te halen", "AFM en Belastingdienst geven geen verklaringen van herkomst af; de instelling onderzoekt dit zelf."]], "4a.1"],
["Een Wwft-instelling heeft een ongebruikelijke transactie van een klant gemeld. Mag zij de klant daarover informeren?", [["Nee, de instelling mag de klant niet vertellen dat een melding is gedaan", "De Wwft verbiedt het informeren van de klant over een melding, zodat het onderzoek niet wordt gefrustreerd."], ["Ja, de klant heeft op grond van de AVG altijd recht op inzage in de melding", "Het inzagerecht uit de AVG geldt hier niet; de geheimhoudingsplicht uit de Wwft gaat voor."], ["Ja, maar alleen schriftelijk en pas na afloop van de transactie aan de klant zelf", "Ook na afloop mag de klant niet over de melding worden ingelicht."], ["Alleen als de klant een hypotheek met NHG heeft", "NHG heeft geen enkele invloed op de geheimhoudingsplicht."]], "1a.3"],
["Sem (33) en Laura (37) kopen samen een woning in Amersfoort, ieder voor de helft. Het is voor beiden de eerste koopwoning en zij gaan er zelf wonen. De koopsom ligt onder de woningwaardegrens voor de startersvrijstelling. Sem werkt als elektricien, Laura als HR-adviseur. Wat geldt voor de overdrachtsbelasting?", [["Sem is vrijgesteld voor zijn helft; Laura betaalt het verlaagde tarief over haar helft", "De startersvrijstelling wordt per verkrijger beoordeeld; Laura voldoet niet aan de leeftijdseis van jonger dan 35 jaar."], ["Beiden zijn vrijgesteld, omdat een van hen jonger is dan 35 jaar", "De vrijstelling geldt per persoon, niet per huishouden."], ["Beiden betalen over hun eigen helft het verlaagde tarief, omdat Laura ouder is dan 35 jaar", "Sem verliest zijn vrijstelling niet doordat Laura er niet aan voldoet."], ["Beiden betalen het algemene tarief, omdat zij samen een woning kopen", "Samen kopen is geen reden voor het algemene tarief; zij gaan de woning zelf bewonen."]], "1a.1"],
["Ilse (28) is tandartsassistente en koopt haar eerste woning, een eengezinswoning in Hoorn. Zij gaat er zelf wonen en heeft nog nooit gebruikgemaakt van de startersvrijstelling. De koopsom ligt net iets boven de woningwaardegrens voor die vrijstelling. Zij hoopt dat zij alleen over het meerdere hoeft te betalen. Wat is het gevolg?", [["Zij heeft geen recht op de vrijstelling en betaalt over de hele koopsom het verlaagde tarief", "De woningwaardegrens is een harde grens: daarboven vervalt de vrijstelling geheel en geldt het verlaagde tarief voor eigen bewoning."], ["Zij betaalt alleen overdrachtsbelasting over het deel boven de woningwaardegrens", "De vrijstelling werkt niet als drempel; boven de grens vervalt zij volledig."], ["Zij betaalt het algemene tarief over de hele koopsom, omdat de woningwaardegrens is overschreden", "Omdat zij de woning zelf gaat bewonen, geldt het verlaagde tarief en niet het algemene tarief."], ["Zij behoudt de vrijstelling als zij de woning binnen een jaar na aankoop verbouwt", "Een verbouwing na aankoop heeft geen invloed op de vrijstelling."]], "1a.1"],
["Een klant heeft een kapitaalverzekering eigen woning (KEW) uit 2008 die aan zijn hypotheek is verpand. Hij wil de polis vóór de einddatum afkopen en het geld gebruiken voor een nieuwe auto; de hypotheek blijft gelijk. Wat is het fiscale gevolg?", [["De vrijstelling vervalt en het rentebestanddeel van de afkoopsom wordt belast in box 1", "De vrijstelling voor een KEW geldt alleen als de uitkering wordt gebruikt voor aflossing van de eigenwoningschuld; anders is het rentebestanddeel belast."], ["De afkoopsom is volledig vrijgesteld, omdat de polis al ruim vijftien jaar loopt", "De looptijd alleen is niet genoeg; de uitkering moet ook voor aflossing van de eigenwoningschuld worden gebruikt."], ["De afkoopsom valt als bezitting in box 3 en is verder onbelast", "Het rentebestanddeel wordt bij afkoop zonder aflossing belast in box 1, niet alleen als bezitting in box 3."], ["De betaalde premies worden alsnog als aftrekpost in box 1 toegekend", "Premies voor een KEW zijn nooit aftrekbaar geweest, ook niet bij afkoop."]], "1e.12"],
["Bas (35) is accountmanager met € 65.000 bruto per jaar en Merel (34) is parttime docent met € 30.000 bruto per jaar. Zij willen een gezinswoning kopen in Amersfoort. Merel heeft gehoord dat het tweede inkomen bij de hypotheek maar voor een deel meetelt. Zij vragen hun adviseur hoe dat zit. Hoe telt het inkomen van Merel volgens de leennormen mee in het toetsinkomen?", [["Volledig, net als het hoogste inkomen; de beperking voor het tweede inkomen is vervallen", "Sinds 2024 telt het inkomen van de minstverdienende partner volledig mee in het toetsinkomen."], ["Voor de helft, om het risico van uitval van het tweede inkomen bij de geldverstrekker op te vangen", "Een gedeeltelijke weging gold in het verleden; sinds 2024 telt het tweede inkomen volledig mee."], ["Niet, alleen het hoogste inkomen bepaalt hun maximale hypotheek", "Ook het tweede inkomen telt mee in het toetsinkomen."], ["Alleen als beide partners een vast contract voor onbepaalde tijd hebben", "Een vast contract is geen voorwaarde om het tweede inkomen mee te tellen."]], "1i.4"],
["Wat gebeurt er in de regel op de dag van de eigendomsoverdracht bij de notaris?", [["De akten worden getekend en de notaris betaalt de verkoper via de derdengeldenrekening", "De notaris ontvangt vooraf het geld van de geldverstrekker en de koper, laat de akten tekenen, betaalt de verkoper uit en laat de akten inschrijven."], ["De koper betaalt de koopsom contant aan de verkoper in aanwezigheid van de makelaar", "Contante betaling is ongebruikelijk; het geld loopt via de notaris."], ["De geldverstrekker stort de lening op de privérekening van de koper, die de verkoper betaalt", "Het hypotheekbedrag gaat naar de derdengeldenrekening van de notaris, niet naar de koper."], ["Alleen de koopovereenkomst wordt getekend; de levering volgt na enkele maanden", "De koopovereenkomst is al eerder gesloten; bij de notaris vindt de levering plaats."]], "1b.7"],
["Hoe verhoudt het financieringslastpercentage in de TRHK zich in het algemeen tot de hoogte van het toetsinkomen?", [["Bij een hoger inkomen is het percentage hoger", "Wie meer verdient, houdt na de vaste basisuitgaven relatief meer over en kan dus een groter deel van zijn inkomen aan woonlasten besteden."], ["Het percentage is voor alle inkomens gelijk, alleen de rente maakt verschil", "De tabellen variëren juist met het inkomen; een vast percentage voor iedereen zou lagere inkomens te zwaar belasten."], ["Bij een hoger inkomen is het percentage lager, omdat de belastingdruk stijgt", "Het percentage loopt met het inkomen op; de hogere belastingdruk is al verwerkt en draait dat niet om."], ["Het percentage hangt alleen af van de leeftijd van de aanvrager", "Leeftijd speelt alleen een rol rond de AOW-leeftijd; de hoogte van het inkomen en de toetsrente bepalen het percentage."]], "1a.2"],
["Rick (37) werkt als ICT-beheerder en heeft een toetsinkomen van € 60.000. Hij wil alleen een appartement kopen in Leeuwarden. Bij zijn inkomen en de geldende toetsrente hoort volgens de tabel een financieringslastpercentage van 25%. Hij heeft geen andere financiële verplichtingen. Wat is zijn maximale bruto maandlast voor rente en aflossing?", [["€ 1.250 per maand", "€ 60.000 × 25% = € 15.000 per jaar, gedeeld door 12 is € 1.250 per maand."], ["€ 1.500 per maand", "Dit gaat uit van 30% in plaats van 25%."], ["€ 15.000 per maand", "€ 15.000 is de maximale jaarlast, niet de maandlast."], ["€ 937,50 per maand", "Dit is 75% van de juiste maandlast; het percentage is verkeerd toegepast."]], "1i.4"],
["Wat moet een kredietgever doen als uit de kredietwaardigheidsbeoordeling blijkt dat de gevraagde hypotheek niet verantwoord is?", [["Het krediet in deze vorm niet verstrekken, ook niet op verzoek van de klant", "De Wft verbiedt overkreditering: blijkt het krediet onverantwoord, dan mag de kredietgever het niet aangaan."], ["Het krediet verstrekken als de klant een verklaring tekent dat hij het risico aanvaardt", "Een afstandsverklaring van de klant heft het verbod op overkreditering niet op; de verantwoordelijkheid ligt bij de kredietgever."], ["Het krediet verstrekken tegen een hogere rente als compensatie voor het risico", "Een hogere rente maakt een onverantwoorde lening alleen maar zwaarder en is geen oplossing voor overkreditering."], ["Het krediet verstrekken, maar dit binnen een maand melden aan de AFM", "Er bestaat geen meldroute die overkreditering toelaatbaar maakt; het krediet mag dan niet worden verstrekt."]], "1a.3"],
["Nadia (30) werkt als marketingadviseur en wil met haar partner Tom (31) een woning in Utrecht kopen. Zij rijdt een private-leaseauto waarvoor zij elke maand een vast bedrag betaalt; het contract loopt nog drie jaar. Tom denkt dat dit bij de hypotheekaanvraag niet uitmaakt, omdat het een huurcontract is. Hoe gaat de kredietgever in beginsel om met de private lease?", [["De leasetermijn telt mee als vaste financiële verplichting en verlaagt de leencapaciteit", "Private lease is een vaste maandelijkse verplichting die op het budget drukt en wordt daarom meegewogen."], ["Private lease is juridisch huur van een auto en blijft daarom bij de toetsing altijd buiten beschouwing", "Ook al is het juridisch huur, de vaste last drukt op de betaalcapaciteit en telt dus mee."], ["Alleen de restwaarde van de auto aan het einde van het contract telt mee", "Bij private lease is er geen restwaarde voor de klant; het gaat om de maandtermijn."], ["De leaseauto verhoogt de leencapaciteit, omdat hij als bezitting meetelt", "De auto is eigendom van de leasemaatschappij, niet van de klant."]], "1i.4"],
["Een klant koopt een nieuwbouwwoning van een projectontwikkelaar. Waarop wordt de woningwaarde voor de LTV-toets bij nieuwbouw doorgaans gebaseerd?", [["Op de koop-/aanneemsom inclusief meerwerk", "Bij nieuwbouw dient de vrij-op-naamprijs met het meerwerk als waarde; een taxatie is dan meestal niet nodig."], ["Op de WOZ-waarde die de gemeente na oplevering vaststelt", "De WOZ-waarde is er bij aankoop nog niet en wordt voor de LTV-toets niet gebruikt."], ["Op de grondwaarde, omdat de opstal nog gebouwd moet worden", "De financiering ziet op de complete woning; alleen de grondwaarde zou de waarde sterk onderschatten."], ["Op een gemiddelde van vergelijkbare bestaande woningen in de buurt", "Zo'n gemiddelde is geen toetsmaatstaf; bij nieuwbouw is de koop-/aanneemsom met meerwerk het uitgangspunt."]], "1a.2"],
["Wat hoort een geldverstrekker richting de klant te doen rond het einde van een rentevaste periode?", [["De klant tijdig vooraf informeren over de renteherziening en het nieuwe aanbod", "Zo kan de klant op tijd kiezen voor een nieuwe periode of vergelijken met andere aanbieders."], ["De rente automatisch voor dezelfde periode verlengen zonder de klant te informeren", "Stilzwijgend verlengen zonder informatie zou de keuzevrijheid van de klant ondermijnen; van de geldverstrekker wordt juist tijdige informatie verwacht."], ["De klant verplicht een nieuw hypotheekadvies laten volgen bij een erkend adviseur", "Een renteherziening vereist geen nieuw adviestraject; de klant mag zelf kiezen."], ["De lening volledig opeisen als de klant niet binnen een week reageert", "Het aflopen van de rentevaste periode is geen opeisingsgrond; de lening loopt gewoon door."]], "1a.6"],
["Een klant ontvangt van zijn geldverstrekker een bindend hypotheekaanbod. Wat geldt volgens de regels voor hypothecair krediet aan consumenten?", [["Het aanbod blijft minstens veertien dagen geldig, zodat hij kan vergelijken en nadenken", "Deze bedenktijd uit de hypothekenrichtlijn geeft de consument tijd om het aanbod te beoordelen voordat hij gebonden is."], ["De klant moet het aanbod binnen drie dagen accepteren, anders vervalt het", "Drie dagen is de bedenktijd bij de koopakte van een woning, niet de geldigheid van een hypotheekaanbod."], ["De geldverstrekker mag het aanbod op elk moment intrekken als de rente stijgt", "Tijdens de bedenktijd kan de kredietgever het aanbod niet eenzijdig intrekken vanwege een rentestijging."], ["Een bindend aanbod is pas geldig nadat de notaris de akte heeft gepasseerd", "Het aanbod gaat vooraf aan de akte; de notaris passeert de akte juist op basis van het geaccepteerde aanbod."]], "1a.6"],
["Een klant leent € 200.000 annuïtair in 30 jaar tegen 4% rente. De bruto maandlast is ongeveer € 954,83. Hoeveel lost hij in de eerste maand af?", [["Ongeveer € 288,16", "De rente in maand 1 is € 200.000 × 4% / 12 = € 666,67; de rest van de annuïteit, € 288,16, is aflossing."], ["Ongeveer € 555,56", "Dit is de aflossing bij een lineaire lening (€ 200.000 / 360); bij een annuïteit is de aflossing in het begin lager."], ["Ongeveer € 666,67", "Dit is het rentedeel van de eerste maand, niet het aflossingsdeel."], ["Ongeveer € 954,83", "Dit is de volledige bruto maandlast; daarvan is het grootste deel nog rente."]], "1i.3"],
["Een klant heeft een lineaire hypotheek van € 360.000 met een looptijd van 30 jaar en een rente van 4,2%. Met hoeveel daalt de bruto maandlast elke maand?", [["€ 3,50", "Hij lost elke maand € 1.000 af (€ 360.000 / 360); de rente daarover is € 1.000 × 4,2% / 12 = € 3,50 minder per maand."], ["€ 1.000,00", "Dit is het vaste maandelijkse aflossingsbedrag, niet de daling van de maandlast."], ["€ 42,00", "Dit is de jaarrente over € 1.000; per maand daalt de rente met een twaalfde daarvan."], ["€ 0,00, de bruto maandlast blijft gelijk zolang de rente vaststaat", "Gelijkblijvende bruto lasten horen bij een annuïteit; bij lineair dalen de lasten doordat de schuld afneemt."]], "1i.3"],
["Wat is kenmerkend voor een traditionele spaarhypotheek gekoppeld aan een spaarverzekering?", [["De rente op het spaardeel is gelijk aan de hypotheekrente", "Doordat spaardeel en lening hetzelfde rendement hebben, werkt de constructie netto vergelijkbaar met een annuïteit."], ["Het spaardeel wordt belegd in aandelen met een wisselend rendement", "Beleggen in aandelen is kenmerkend voor de beleggingshypotheek, niet voor de spaarhypotheek."], ["De klant lost maandelijks rechtstreeks af op de lening", "Bij een spaarhypotheek blijft de lening staan en wordt via het spaardeel aan het einde in één keer afgelost."], ["De rente op het spaardeel staat altijd vast voor de hele looptijd", "De spaarrente volgt de hypotheekrente en kan dus bij een renteherziening wijzigen."]], "1e.2"],
["Wat is kenmerkend voor een krediethypotheek (hypothecair doorlopend krediet)?", [["De klant kan binnen een afgesproken limiet geld opnemen en weer terugstorten", "Een krediethypotheek werkt als een doorlopend krediet met de woning als zekerheid; de rente is vaak variabel."], ["De klant ontvangt het hele bedrag ineens en lost in vaste termijnen af", "Dat beschrijft een gewone annuïtaire of lineaire lening, niet een doorlopende kredietfaciliteit."], ["De rente wordt nooit in rekening gebracht zolang de klant niets opneemt", "Over het niet-opgenomen deel betaalt de klant geen rente, maar dat is een gevolg en niet wat de vorm kenmerkt."], ["De lening wordt automatisch afgelost uit een gekoppelde levensverzekering", "Koppeling aan een verzekering is kenmerkend voor een levenhypotheek, niet voor een krediethypotheek."]], "1i.3"],
["Truus (74) is weduwe en woont in een hypotheekvrije woning in Amstelveen. Haar AOW en kleine pensioen zijn net genoeg voor de vaste lasten, maar zij wil haar badkamer laten aanpassen en haar kleinkinderen helpen. Een aanbieder biedt haar een verzilverhypotheek aan waarbij zij geen maandlasten betaalt en de rente wordt bijgeschreven. Haar dochter vraagt de adviseur wat het grootste risico is. Welk risico hoort de adviseur vooral te bespreken?", [["De schuld groeit door de bijgeschreven rente en kan de overwaarde van de woning opeten", "Doordat rente op rente wordt bijgeschreven, kan de schuld snel oplopen en de overwaarde voor haar of haar erfgenamen verkleinen."], ["De maandlasten kunnen bij een rentestijging direct en fors toenemen", "Bij een verzilverhypotheek betaalt zij juist geen maandlasten; de rente wordt bijgeschreven."], ["Zij moet de lening na tien jaar in één keer volledig aflossen", "Een verzilverhypotheek wordt doorgaans pas afgelost bij verkoop of overlijden."], ["De woning komt direct na het afsluiten van de verzilverhypotheek in eigendom van de geldverstrekker", "Zij blijft eigenaar; de geldverstrekker krijgt alleen een hypotheekrecht."]], "1i.2"],
["Kim (36) en Ali (38) hebben vier jaar geleden een hypotheek afgesloten met een rente van 2% die nog zes jaar vaststaat. Met hun tweede kind op komst kopen zij een grotere woning in Haarlem. De rente is inmiddels flink hoger dan hun huidige rente. Zij willen hun lage rente graag behouden voor het bedrag dat zij al lenen. Welke productvoorwaarde maakt dat mogelijk?", [["Een meeneemregeling (verhuisregeling) in hun huidige hypotheekvoorwaarden", "Met een meeneemregeling kan de bestaande lening met de rente en de resterende rentevaste periode naar de nieuwe woning worden meegenomen."], ["Een rentedaalgarantie in de offerte voor de nieuwe woning", "Een rentedaalgarantie gaat over een rentedaling tijdens de offerteperiode, niet over het behouden van een oude rente."], ["Een overbruggingskrediet op hun huidige woning tot de verkoop", "Een overbrugging maakt overwaarde tijdelijk beschikbaar, maar behoudt de rente niet."], ["Een plafondrente op het nieuwe leningdeel voor de grotere woning", "Een plafondrente begrenst een variabele rente en zegt niets over het meenemen van de oude rente."]], "1h.6"],
["Wat is een starterslening, zoals sommige gemeenten die aanbieden?", [["Een aanvullende lening naast de eerste hypotheek op de woning", "De starterslening komt boven op de reguliere hypotheek en heeft vaak gunstige voorwaarden in de eerste jaren."], ["Een subsidie die de starter niet hoeft terug te betalen", "Het is een lening die wel moet worden terugbetaald, ook al zijn de eerste jaren vaak rente- en aflossingsvrij."], ["Een hypotheek die de verplichting tot NHG vervangt", "Een starterslening is aanvullend en vervangt NHG niet; vaak worden ze juist samen gebruikt."], ["Een vrijstelling van overdrachtsbelasting voor jonge kopers", "De startersvrijstelling is een belastingregel; de starterslening is een financieringsproduct."]], "1b.6"],
["Hans (63) heeft sinds 2010 een aflossingsvrij leningdeel van € 120.000 op zijn woning in Assen. Hij wil zijn hypotheek vóór zijn pensioen flink verlagen en overweegt dit deel om te zetten in een annuïtaire lening. Hij is bang dat hij daarmee zijn renteaftrek kwijtraakt. Zijn adviseur zoekt uit wat de fiscale gevolgen zijn. Wat is fiscaal juist?", [["Het leningdeel blijft eigenwoningschuld en de rente blijft aftrekbaar", "Omzetten van een schuld onder het overgangsrecht naar een aflossende vorm laat de renteaftrek intact."], ["Het leningdeel valt na de omzetting voortaan in box 3", "Aflossen maakt de lening niet tot een box 3-schuld."], ["Hij krijgt een nieuwe dertigjaarstermijn vanaf de datum van omzetting", "De bestaande looptijd voor renteaftrek loopt door; een omzetting start geen nieuwe termijn."], ["De omzetting is alleen toegestaan met toestemming van de Belastingdienst", "Voor omzetting is geen toestemming van de Belastingdienst nodig."]], "1a.1"],
["Wanneer is een woning fiscaal een eigen woning in de zin van de Wet IB 2001?", [["Als zij hem (en zijn huishouden) duurzaam als hoofdverblijf ter beschikking staat", "Het hoofdverblijfcriterium is de kern van de eigenwoningregeling (meestal krachtens eigendom); een tweede woning of beleggingspand valt erbuiten."], ["Als de klant er ingeschreven staat, ook als hij er feitelijk niet woont", "De inschrijving in de BRP is een aanwijzing, maar het feitelijke hoofdverblijf is beslissend."], ["Als de woning met een hypotheek is gefinancierd, ongeacht wie erin woont", "Financiering met een hypotheek maakt een woning nog geen eigen woning; het gaat om het hoofdverblijf."], ["Als de klant er minstens drie maanden per jaar verblijft", "Een minimumaantal maanden is niet het criterium; het moet het hoofdverblijf zijn."]], "1a.1"],
["Een klant heeft sinds 1995 een hypotheek op zijn eigen woning. Vanaf welk moment loopt de 30-jaarstermijn voor renteaftrek over deze schuld?", [["Vanaf 1 januari 2001", "Voor schulden van vóór de Wet IB 2001 is de termijn op 1 januari 2001 gaan lopen; de aftrek eindigt dus uiterlijk eind 2030."], ["Vanaf de datum van het afsluiten in 1995", "De termijn van 30 jaar bestond in 1995 nog niet; voor bestaande schulden is gestart op 1 januari 2001."], ["Vanaf 1 januari 2013", "In 2013 ging de aflossingseis in, maar de 30-jaarstermijn voor oude schulden liep al sinds 2001."], ["Er geldt geen termijn, oude schulden hebben onbeperkte aftrek", "Ook schulden van vóór 2001 vallen onder de maximale aftrekduur van 30 jaar."]], "1a.1"],
["Een klant koopt een woning. Welke notariskosten zijn als financieringskosten direct aftrekbaar in box 1?", [["De notariskosten voor het opmaken van de hypotheekakte", "Kosten van de hypotheekakte zijn kosten van het afsluiten van de lening en daarom aftrekbaar."], ["De notariskosten voor de leveringsakte", "De leveringsakte hoort bij de verwerving van de woning; die kosten zijn niet aftrekbaar, wel financierbaar."], ["De overdrachtsbelasting die de notaris namens de staat int", "Overdrachtsbelasting hoort bij de verwervingskosten en is niet aftrekbaar."], ["Het kadastrale inschrijvingsrecht voor de eigendomsoverdracht", "Kosten voor de inschrijving van de levering zijn verwervingskosten en niet direct aftrekbaar."]], "1e.7"],
["Een klant financiert de kosten koper, zoals overdrachtsbelasting en leveringskosten, mee in de hypotheek. Wat is fiscaal juist?", [["Het leningdeel voor de kosten koper kan eigenwoningschuld zijn", "Verwervingskosten tellen mee voor de eigenwoningschuld; de rente erover is aftrekbaar als aan de overige eisen is voldaan."], ["De kosten zelf zijn direct aftrekbaar en het leningdeel valt in box 3", "Het is net andersom: de kosten zijn niet aftrekbaar, maar het leningdeel kan wel eigenwoningschuld zijn."], ["Kosten koper mogen nooit worden geleend, ook niet buiten de TRHK", "Fiscaal kan het; de LTV-norm beperkt wel hoeveel er boven de marktwaarde mag worden geleend."], ["Het leningdeel is alleen aftrekbaar als het aflossingsvrij is", "Een aflossingsvrije lening na 2012 voldoet juist niet aan de aflossingseis en geeft geen aftrek."]], "1e.7"],
["Tegen welk tarief is de hypotheekrente op een eigenwoningschuld voor een klant met een hoog inkomen maximaal aftrekbaar?", [["Tegen een wettelijk gemaximeerd percentage dat lager ligt dan het toptarief", "Het tarief waartegen aftrekposten van de eigen woning worden verrekend, is afgebouwd en gemaximeerd; ook een inkomen in de hoogste schijf levert niet meer op."], ["Tegen het toptarief, omdat zijn inkomen in de hoogste schijf valt", "Aftrek tegen het toptarief is afgebouwd; het voordeel is gemaximeerd."], ["Tegen het tarief van box 3 over het saldo van bezittingen en schulden", "De eigen woning valt in box 1; het box 3-tarief speelt bij de renteaftrek geen rol."], ["Tegen een vast percentage van de WOZ-waarde van de woning", "Een percentage van de WOZ-waarde is het eigenwoningforfait, geen aftrektarief."]], "1h.4"],
["Wat geldt voor een eigen woning met een WOZ-waarde boven de grens waarboven het hogere forfait (de 'villataks') geldt?", [["Een hoger forfaitpercentage over het meerdere", "Het eigenwoningforfait is voor dure woningen verhoogd over het meerdere boven de grens, om de aftrek per saldo te beperken."], ["Over de hele WOZ-waarde vervalt het eigenwoningforfait", "Het forfait vervalt niet; het wordt boven de grens juist hoger."], ["De hypotheekrente is boven die grens niet meer aftrekbaar", "De renteaftrek blijft gewoon bestaan; alleen het forfait wordt boven de grens verhoogd."], ["De woning valt boven die grens geheel in box 3", "Ook een dure woning blijft een eigen woning in box 1 als zij het hoofdverblijf is."]], "1h.4"],
["Michiel (45) en Anouk (43) zijn getrouwd en gaan scheiden. Michiel vertrekt in maart 2026 uit hun gezamenlijke woning in Gouda en gaat huren; Anouk blijft er met de kinderen wonen. Michiel betaalt voorlopig de helft van de hypotheekrente. Hij vraagt of hij die rente nog mag aftrekken. Hoe lang kan hij de woning fiscaal nog als eigen woning behandelen?", [["Maximaal twee jaar na zijn vertrek, zolang Anouk als (gewezen) partner in de woning blijft wonen", "De vertrekkende partner kan de woning maximaal twee jaar als eigen woning behandelen zolang de (gewezen) partner er blijft wonen."], ["Tot de echtscheiding in de registers is ingeschreven; daarna valt zijn deel van de woning direct in box 3", "De inschrijving van de scheiding is niet het beslissende moment; de wet kent een termijn van twee jaar."], ["Zolang hij mede-eigenaar blijft, ook als de woning later wordt verhuurd", "Bij verhuur is de woning geen eigen woning; mede-eigendom alleen is niet genoeg."], ["Drie jaar, net als bij een leegstaande woning die te koop staat", "De termijn van drie jaar hoort bij leegstand; bij een scheiding geldt maximaal twee jaar."]], "1a.1"],
["Een klant wil een schenking van zijn ouders gebruiken om op zijn eigenwoningschuld af te lossen. Wat geldt sinds 1 januari 2024 voor de schenkvrijstelling eigen woning?", [["Die is per 1 januari 2024 volledig afgeschaft", "De verhoogde vrijstelling voor de eigen woning (de 'jubelton') bestaat sinds 2024 niet meer."], ["Die is verhoogd voor kinderen jonger dan 40 jaar", "De vrijstelling is niet verhoogd maar volledig afgeschaft."], ["Die geldt alleen nog voor aflossing en niet meer voor aankoop", "De vrijstelling is voor alle eigenwoningbestedingen vervallen, ook voor aflossing."], ["Die mag sinds 2024 over drie jaren worden gespreid", "Spreiding was een kenmerk van de oude regeling; sinds 2024 bestaat de hele vrijstelling niet meer."]], "1a.1"],
["Robin (29) wil een appartement in Groningen kopen met NHG. Hij werkt sinds kort in Rotterdam en is van plan de woning direct aan studenten te verhuren. Over een paar jaar wil hij er misschien zelf gaan wonen. Hij hoopt met NHG een lagere rente te krijgen. Wat is juist?", [["NHG is niet mogelijk, omdat de woning bestemd moet zijn voor eigen bewoning", "NHG is bedoeld voor woningen die de consument zelf gaat bewonen."], ["NHG is mogelijk als de huurinkomsten de maandlasten volledig dekken", "De dekking door huurinkomsten verandert niets aan de eis van eigen bewoning."], ["NHG is mogelijk, maar tegen een dubbele borgtochtprovisie", "Een dubbele provisie voor verhuur bestaat niet; NHG is dan niet mogelijk."], ["NHG is mogelijk als de huurders ook een NHG-verklaring ondertekenen", "Een verklaring van huurders bestaat niet; eigen bewoning is vereist."]], "1b.3"],
["Waar staan de voorwaarden waaraan een NHG-lening moet voldoen?", [["In de Voorwaarden & Normen van de Stichting WEW", "De Stichting WEW stelt deze voorwaarden vast en past ze periodiek aan, onder meer de kostengrens."], ["In de Gedragscode Hypothecaire Financieringen", "De GHF bevat minimumeisen voor offertes en voorwaarden, niet de NHG-normen."], ["In de Wet inkomstenbelasting 2001", "De Wet IB regelt de fiscale behandeling, niet de voorwaarden voor de borgtocht."], ["In het Besluit Gedragstoezicht financiële ondernemingen", "Dat besluit bevat Wft-gedragsregels; de NHG-voorwaarden zijn privaatrechtelijk vastgesteld door de stichting."]], "1b.3"],
["Een klant wil met NHG ook energiebesparende maatregelen meefinancieren. Wat geldt voor de NHG-kostengrens?", [["Die mag voor energiebesparende voorzieningen worden verhoogd", "De Voorwaarden & Normen bieden extra ruimte boven de gewone kostengrens voor energiebesparende maatregelen."], ["Die geldt dan niet meer, het hele bedrag valt onder NHG", "Er blijft een maximum gelden; de extra ruimte voor verduurzaming is begrensd."], ["Die wordt lager, omdat duurzame woningen minder risico lopen", "Verduurzaming leidt niet tot een lagere grens; de regeling stimuleert juist extra ruimte."], ["Verduurzaming kan nooit met NHG worden gefinancierd", "Verduurzaming kan juist onder voorwaarden met NHG worden meegefinancierd."]], "1b.3"],
["In welk register moet een taxateur die een woning taxeert voor een hypothecaire financiering in Nederland zijn ingeschreven?", [["In het Nederlands Register Vastgoed Taxateurs (NRVT)", "Geldverstrekkers en validatie-instituten accepteren voor hypotheken alleen rapporten van in het NRVT ingeschreven taxateurs."], ["In het register van financiële dienstverleners van de AFM", "Het AFM-register is voor financiële dienstverleners; taxateurs staan in het NRVT."], ["In het Kadaster", "Het Kadaster registreert onroerende zaken en rechten, geen taxateurs."], ["In het register van Kifid", "Kifid behandelt klachten over financiële diensten en houdt geen register van taxateurs bij."]], "1b.3"],
["Een klant koopt een nieuwbouwwoning waarvoor in de koopovereenkomst een anti-speculatiebeding geldt. Wat betekent dit voor hem?", [["Hij mag de woning gedurende een bepaalde periode niet zonder toestemming of boete verkopen of verhuren", "Het beding moet voorkomen dat kopers snel met winst doorverkopen of gaan verhuren; het beperkt de verkoopbaarheid tijdelijk."], ["Hij mag de woning nooit voor meer dan de koopsom verkopen", "Het beding geldt voor een bepaalde periode, niet voor altijd."], ["Hij mag de woning niet als onderpand voor een hypotheek gebruiken", "Financieren met een hypotheek blijft mogelijk; het beding gaat over doorverkoop en verhuur."], ["Hij krijgt korting op de overdrachtsbelasting zolang hij de woning binnen de afgesproken periode niet verkoopt", "Het beding heeft geen invloed op de overdrachtsbelasting; het beperkt alleen doorverkoop en verhuur."]], "1f.1"],
["Waarom gebruikt een geldverstrekker voor een nieuwe financiering in de regel niet de WOZ-waarde als basis voor de LTV?", [["Omdat zij voor de belastingheffing dient en achterloopt op de markt", "De WOZ-waarde loopt achter op de markt en is niet bedoeld als actuele marktwaarde voor een financiering."], ["Omdat de WOZ-waarde altijd hoger is dan de marktwaarde", "De WOZ-waarde kan lager of hoger uitvallen; het probleem is dat zij niet actueel en niet voor financiering bedoeld is."], ["Omdat de AFM het gebruik van de WOZ-waarde verbiedt bij alle hypotheken", "Er is geen algemeen verbod; sommige geldverstrekkers gebruiken de WOZ-waarde wel bij beperkte verhogingen."], ["Omdat de WOZ-waarde alleen voor huurwoningen wordt vastgesteld", "De gemeente stelt voor alle woningen een WOZ-waarde vast, ook voor koopwoningen."]], "1b.3"],
["Een klant koopt een bouwkavel en laat daarop in eigen beheer een woning bouwen door een aannemer. Wat is kenmerkend voor de financiering?", [["Het geld voor de bouw komt in een bouwdepot en wordt uitbetaald naarmate de bouw vordert", "Bij eigenbouw betaalt de klant de aannemer in termijnen; via het bouwdepot komt geld pas vrij op facturen voor de voortgang."], ["De hele lening wordt bij de notaris direct op de privérekening van de klant gestort", "Het bouwbedrag wordt niet in één keer aan de klant uitbetaald, maar via het depot op basis van facturen."], ["Een hypotheek is pas mogelijk nadat de woning helemaal klaar is", "De kavel kan al als onderpand dienen; de verwachte waarde na bouw wordt meegenomen in de beoordeling."], ["Het risico van meerwerk en vertraging ligt bij eigenbouw altijd bij de geldverstrekker", "Meerwerk en vertraging komen voor rekening van de klant; een financiële buffer is daarom verstandig."]], "1f.2"],
["Wanneer gaat de eigendom van een woning bij aankoop juridisch over op de koper?", [["Bij inschrijving van de leveringsakte in het Kadaster", "Voor de overdracht van een onroerende zaak is een notariële akte en inschrijving in het Kadaster vereist."], ["Bij ondertekening van de koopovereenkomst bij de makelaar", "De koopovereenkomst verplicht tot levering, maar draagt de eigendom nog niet over."], ["Bij betaling van de waarborgsom of bankgarantie", "De waarborgsom is zekerheid voor de verkoper; de eigendom gaat pas over bij levering."], ["Bij afgifte van de sleutels door de verkoper", "Het overhandigen van de sleutels is feitelijke levering, geen juridische eigendomsoverdracht."]], "1b.5"],
["Een particuliere koper tekent op maandag de koopakte voor een woning en ontvangt die dezelfde dag. Wat geldt?", [["Hij heeft drie dagen wettelijke bedenktijd na ontvangst van de akte", "Het BW geeft een consument-koper van een woning drie dagen bedenktijd na terhandstelling van de koopakte."], ["Hij heeft veertien dagen bedenktijd, zoals bij koop op afstand", "Veertien dagen geldt bij koop op afstand; bij woningkoop is de bedenktijd drie dagen."], ["Hij kan alleen ontbinden als de financiering niet rond komt", "Een financieringsvoorbehoud is een aparte ontbindende voorwaarde; de bedenktijd staat daar los van."], ["Hij heeft geen bedenktijd, omdat hij persoonlijk heeft getekend", "Ook bij persoonlijk tekenen heeft een particuliere koper wettelijke bedenktijd."]], "1b.9"],
["Wat is een wettelijk vereiste voor de koop van een woning door een consument?", [["De koopovereenkomst moet schriftelijk worden aangegaan", "Bij koop van een woning door een consument is de koop pas tot stand gekomen als deze schriftelijk is vastgelegd."], ["De koopovereenkomst moet door een notaris worden opgesteld", "De koopakte wordt vaak door een makelaar opgesteld; alleen de leveringsakte is notarieel."], ["De koopprijs moet zijn goedgekeurd door de taxateur", "Een taxatie is geen voorwaarde voor een geldige koopovereenkomst."], ["De koper moet bij ondertekening een hypotheekofferte overleggen", "Een offerte is geen voorwaarde voor de koop; daarvoor dient eventueel een financieringsvoorbehoud."]], "1b.5"],
["Femke (31) en Luuk (33) hebben een woning in Zwolle gekocht met een financieringsvoorbehoud tot 1 december. Op 20 november wijst de geldverstrekker hun aanvraag af, omdat het tijdelijke contract van Luuk niet wordt meegenomen. Een tweede geldverstrekker kan niet vóór 1 december een besluit nemen. De verkoper weet er nog niets van. Wat kunnen zij doen?", [["Vóór 1 december ontbinden met een beroep op het voorbehoud en de afwijzing meesturen", "Een beroep op het financieringsvoorbehoud moet tijdig en volgens de koopakte worden gedaan, meestal met bewijs van de afwijzing."], ["Niets, de koop staat vast zodra de wettelijke bedenktijd voorbij is", "Na de bedenktijd kan de koper nog steeds een beroep doen op een ontbindende voorwaarde."], ["Ontbinden, maar alleen tegen betaling van de boete uit de koopakte", "Bij een terecht beroep op het voorbehoud is geen boete verschuldigd."], ["De koop na 1 december alsnog ontbinden zodra ook de tweede bank afwijst", "Na de afgesproken datum is het voorbehoud verlopen en is ontbinden op die grond niet meer mogelijk."]], "1b.9"],
["Wat is het doel van de bankgarantie of waarborgsom die een koper na het tekenen van de koopakte stelt?", [["Zekerheid voor de verkoper bij wanprestatie van de koper", "Komt de koper niet na, dan kan de verkoper een boete verhalen op de waarborgsom of bankgarantie."], ["Een eerste aflossing op de nieuwe hypotheek", "De waarborgsom is geen aflossing; zij wordt bij de levering verrekend met de koopsom."], ["Betaling van de makelaarscourtage die de verkoper verschuldigd is", "De courtage is een afspraak tussen verkoper en makelaar en staat los van de waarborgsom."], ["Een borg voor de NHG-borgtochtprovisie", "De NHG-provisie wordt bij de financiering betaald en heeft niets met de waarborgsom te maken."]], "1b.9"],
["Waarvoor gebruikt de notaris bij een woningtransactie een derdengeldenrekening?", [["Om de gelden van alle partijen veilig af te wikkelen", "Het geld staat afgescheiden van het vermogen van de notaris en wordt pas na inschrijving van de akten uitbetaald."], ["Om de notariskosten vooraf te innen bij de koper", "De rekening is niet bedoeld voor eigen kosten van de notaris maar voor gelden van derden."], ["Om de overdrachtsbelasting een jaar te laten renderen", "De notaris draagt overdrachtsbelasting af en mag geld van derden niet voor eigen rendement gebruiken."], ["Om de lening tijdens de looptijd te beheren voor de geldverstrekker", "Na de afwikkeling heeft de notaris geen rol meer in het beheer van de lening."]], "1b.7"],
["Wat is in beginsel het verschil tussen een borg en een medeschuldenaar bij een hypothecaire lening?", [["Een borg is pas aanspreekbaar als de hoofdschuldenaar tekortschiet; een medeschuldenaar direct voor de hele schuld", "Een borg staat in voor de schuld van een ander; een medeschuldenaar is zelf hoofdelijk schuldenaar."], ["Een borg is direct voor de hele schuld aansprakelijk; een medeschuldenaar pas als de hoofdschuldenaar zelf niet betaalt", "Dit is precies andersom: de medeschuldenaar is zelf schuldenaar, de borg staat in voor een ander."], ["Een borg en een medeschuldenaar zijn allebei alleen aansprakelijk voor de helft van de lening en de rente", "Een medeschuldenaar is hoofdelijk voor de hele schuld aansprakelijk, niet voor de helft."], ["Een borg moet altijd mede-eigenaar van de woning zijn; een medeschuldenaar hoeft dat nooit te zijn", "Een borg hoeft geen eigenaar te zijn; ook een medeschuldenaar kan wel of niet mede-eigenaar zijn."]], "1f.4"],
["Wat betekent het dat een hypotheekrecht een afhankelijk (accessoir) recht is?", [["Het bestaat alleen zolang de vordering bestaat die het zekert", "Een hypotheekrecht volgt de vordering; is de schuld voldaan (bij een gewone hypotheek), dan vervalt het recht."], ["Het is afhankelijk van toestemming van de gemeente", "Voor het vestigen van een hypotheekrecht is geen toestemming van de gemeente nodig."], ["Het kan alleen bestaan als er ook een NHG-borgtocht is", "Een hypotheekrecht bestaat ook zonder NHG; NHG is een aanvullende borgtocht."], ["Het vervalt automatisch als de woning wordt verkocht", "Het hypotheekrecht blijft bij verkoop op de woning rusten tot het is doorgehaald."]], "1f.3"],
["Een klant heeft zijn hypotheek volledig afgelost. Hoe verdwijnt de hypotheekinschrijving uit de openbare registers?", [["Door doorhaling (royement) in de registers", "Na aflossing moet het recht formeel worden doorgehaald in het Kadaster, anders blijft de inschrijving zichtbaar."], ["Automatisch, zodra de laatste termijn is betaald", "Het Kadaster weet niet dat de schuld is afgelost; de doorhaling moet worden aangevraagd."], ["Door een mededeling van de klant aan de gemeente", "De gemeente houdt de hypotheekregisters niet bij; dat doet het Kadaster."], ["Pas als de woning wordt verkocht aan een nieuwe eigenaar", "De doorhaling kan direct na aflossing; het is niet nodig te wachten op verkoop."]], "1j.1"],
["In een hypotheekakte staat een huurbeding. Wat betekent dit voor de hypotheekhouder?", [["Hij kan bij executie een huur zonder zijn toestemming negeren", "Het huurbeding beschermt de executiewaarde: een woning zonder huurder brengt meer op."], ["Hij mag de woning zelf verhuren zolang de klant geen achterstand heeft", "Het huurbeding geeft geen recht om de woning tijdens een normale looptijd te verhuren."], ["Hij ontvangt automatisch een deel van eventuele huurinkomsten", "Het beding regelt geen deling van huur, maar beperkt verhuur zonder toestemming."], ["De klant moet de woning verplicht verhuren als hij verhuist", "Er is geen verhuurplicht; het beding verbiedt juist verhuur zonder toestemming."]], "1e.4"],
["Een klant koopt een appartement. Waarop moet de adviseur in verband met de Vereniging van Eigenaars (VvE) onder meer letten?", [["De VvE-bijdrage en het reservefonds", "Hoge bijdragen of een te klein reservefonds kunnen de woonlasten en de verkoopbaarheid van het appartement sterk raken."], ["Of de VvE ook de hypotheekrente betaalt", "De VvE betaalt nooit de hypotheekrente van een eigenaar; zij beheert het gemeenschappelijke gebouw."], ["Of de VvE de leennormen goedkeurt", "Een VvE heeft geen rol bij de kredietwaardigheidstoets van een eigenaar."], ["Of de VvE toestemming geeft voor de hypotheekakte", "Voor het vestigen van een hypotheek op een appartementsrecht is geen VvE-toestemming nodig."]], "1a.4"],
["Jan (34) kocht in 2021 een appartement in Delft op eigen naam. In 2026 trouwt hij met Sara (32) zonder huwelijkse voorwaarden. Sara trekt bij hem in en zij willen later samen een groter huis kopen. Sara vraagt zich af of het appartement nu ook van haar is. Wat geldt in beginsel?", [["Het appartement blijft van Jan en valt niet in de beperkte gemeenschap", "Sinds 2018 geldt de beperkte gemeenschap van goederen; wat vóór het huwelijk al van een echtgenoot was, blijft privé."], ["Het appartement valt door het huwelijk volledig in de gemeenschap van goederen", "Volledige gemeenschap geldt alleen voor huwelijken van vóór 2018."], ["Het appartement wordt automatisch voor de helft op naam van Sara gezet", "Een huwelijk wijzigt de inschrijving in het Kadaster niet automatisch."], ["De hypotheek valt in de gemeenschap, maar het appartement blijft van Jan", "Een schuld die bij een privégoed hoort, blijft in beginsel ook privé."]], "1a.4"],
["Tim (36) en Lisanne (34) wonen ongehuwd samen en kopen samen een woning in Hengelo, ieder voor de helft. Zij hebben geen testament en geen kinderen. Zij willen dat de langstlevende bij overlijden van de ander de hele woning krijgt. Hun adviseur wijst hen op de mogelijkheden. Hoe kunnen zij dat regelen?", [["Met een verblijvingsbeding in een notarieel samenlevingscontract", "Met een verblijvingsbeding verkrijgt de langstlevende het aandeel van de overledene; zonder testament of beding is de partner geen erfgenaam."], ["Dat gaat automatisch, omdat zij beiden op de hypotheekakte staan", "De hypotheekakte regelt de lening, niet wie het aandeel van de overledene krijgt."], ["Door de woning bij de gemeente als gezamenlijk hoofdverblijf te registreren", "Een inschrijving bij de gemeente heeft geen erfrechtelijke gevolgen."], ["Door een overlijdensrisicoverzekering op naam van één van beiden af te sluiten", "Een verzekering levert geld op, maar regelt niet wie eigenaar van het aandeel wordt."]], "1a.4"],
["Wat houdt rentemiddeling in?", [["De oude rente en de vergoeding voor oversluiten worden verwerkt in een nieuwe, gemiddelde rente", "In plaats van de vergoeding ineens te betalen, gaat de klant een gemiddelde rente betalen voor een nieuwe periode."], ["De rente wordt elk jaar gemiddeld met de rente van andere klanten", "Rentemiddeling is een individuele afspraak bij tussentijds herzien, geen gemiddelde over klanten."], ["De klant betaalt de helft van de rente nu en de rest bij het einde van de looptijd", "Uitstel van rentebetaling is iets anders; bij rentemiddeling blijft de klant gewoon maandelijks rente betalen."], ["De rente wordt gemiddeld met de rente van de vorige geldverstrekker bij oversluiten", "Rentemiddeling gebeurt bij dezelfde geldverstrekker, niet bij oversluiten naar een andere."]], "1e.10"],
["Waardoor wordt de hoogte van een variabele hypotheekrente vooral beïnvloed?", [["Door de korte geldmarktrente, zoals de Euribor", "Variabele rentes bewegen mee met de korte rente waartegen banken geld lenen, aangevuld met opslagen voor kosten en risico."], ["Door de rente op tienjarige staatsleningen", "Lange rentes zijn bepalend voor lange rentevaste periodes, niet voor de variabele rente."], ["Door de stand van de AEX-index", "Aandelenkoersen bepalen de hypotheekrente niet rechtstreeks."], ["Door de jaarlijkse inflatiecorrectie van de NHG-kostengrens", "De NHG-kostengrens is een leengrens en geen rente-indicator."]], "1b.2"],
["Bij welke aflossingsvorm blijft het bedrag dat met een overlijdensrisicoverzekering moet worden gedekt het langst op hetzelfde niveau?", [["Bij een aflossingsvrije lening, omdat de schuld tijdens de looptijd niet daalt", "Zonder aflossing blijft de schuld gelijk, dus ook het bedrag dat bij overlijden moet worden gedekt."], ["Bij een lineaire lening, omdat daarop elke maand hetzelfde bedrag wordt afgelost", "Bij lineair daalt de schuld juist vanaf het begin snel, dus ook het te dekken bedrag."], ["Bij een annuïtaire lening, omdat de bruto maandlast gelijk blijft", "Een gelijke maandlast betekent niet dat de schuld gelijk blijft; de schuld daalt, eerst langzaam en later sneller."], ["Het te dekken bedrag hangt niet af van de aflossingsvorm, alleen van het inkomen", "Het overlijdensrisico hangt samen met de resterende schuld, en die verschilt per aflossingsvorm."]], "1g.2"],
["Bij een normale (oplopende) rentecurve: hoe verhoudt de rente bij een rentevaste periode van 20 jaar zich doorgaans tot die bij 5 jaar?", [["De rente voor 20 jaar is doorgaans hoger, als prijs voor langere zekerheid", "Bij een normale rentecurve is lang geld duurder; de klant betaalt voor zekerheid tegen rentestijging."], ["De rente voor 20 jaar is doorgaans lager, omdat de bank minder administratie heeft", "Administratiekosten bepalen de rente nauwelijks; bij een normale curve ligt lange rente juist hoger."], ["De rentes zijn altijd gelijk, de looptijd maakt niet uit", "Rentes verschillen per periode; daarom is de keuze voor de rentevaste periode zo belangrijk."], ["De rente voor 20 jaar is altijd precies het dubbele van die voor 5 jaar", "Er is geen vaste rekenregel; het verschil hangt af van de markt."]], "1b.2"],
["In welke situatie hoeft een klant volgens de meeste hypotheekvoorwaarden geen vergoeding voor vervroegde aflossing te betalen?", [["Bij verkoop en levering van de woning aan een derde, bijvoorbeeld bij verhuizing", "Bij verkoop en verhuizing is aflossen boetevrij volgens de gangbare voorwaarden; dit sluit aan bij de GHF."], ["Bij oversluiten naar een andere geldverstrekker vanwege een lagere rente", "Oversluiten tijdens de rentevaste periode is juist de typische situatie waarin een vergoeding verschuldigd kan zijn."], ["Bij aflossing uit eigen spaargeld boven de boetevrije ruimte", "Boven de boetevrije ruimte kan een vergoeding verschuldigd zijn als de marktrente lager is."], ["Bij aflossing met geld uit een box 3-belegging tijdens de rentevaste periode", "De herkomst van het geld maakt niet uit; het gaat om het moment en het bedrag van aflossing."]], "1e.10"],
["Wat is de boetevrije aflossingsruimte bij een hypotheek?", [["Het bedrag dat de klant per jaar zonder vergoeding extra mag aflossen", "De omvang verschilt per aanbieder en wordt vaak uitgedrukt als percentage van de oorspronkelijke hoofdsom."], ["De periode na de akte waarin de klant de lening kosteloos kan opzeggen", "Dat is geen boetevrije ruimte; een bedenktijd geldt vóór het aangaan van de lening."], ["Het verschil tussen de marktwaarde en de hoogte van de lening", "Dat verschil is de overwaarde, niet de boetevrije ruimte."], ["Het deel van de lening dat aflossingsvrij mag blijven", "Aflossingsvrij is een aflossingsvorm; de boetevrije ruimte gaat over extra aflossen."]], "1e.10"],
["Olga (52) heeft bij aankoop een hypotheek afgesloten met een oorspronkelijke hoofdsom van € 300.000. Volgens haar voorwaarden mag zij elk jaar 10% van de oorspronkelijke hoofdsom boetevrij extra aflossen. Dit jaar heeft zij nog niets extra afgelost. Zij wil nu met haar bonus en spaargeld € 50.000 aflossen. Over welk bedrag kan een vergoeding wegens vervroegde aflossing verschuldigd zijn?", [["€ 20.000", "Boetevrij is 10% van € 300.000 = € 30.000; over het meerdere van € 20.000 kan een vergoeding gelden."], ["€ 50.000", "Dat is het volledige extra bedrag; de boetevrije ruimte van € 30.000 moet eraf."], ["€ 45.000", "Dit gaat uit van 10% van het afgeloste bedrag in plaats van 10% van de oorspronkelijke hoofdsom."], ["€ 0, omdat extra aflossen altijd boetevrij is", "Extra aflossen boven de boetevrije ruimte is niet altijd boetevrij; dat hangt af van het renteverschil."]], "1e.10"],
["Gijs (48) lost € 50.000 af boven de boetevrije ruimte van zijn hypotheek. Zijn contractrente is 4,5% en staat nog precies vier jaar vast. De actuele rente van zijn geldverstrekker voor een rentevaste periode van vier jaar is 3,5%. Hij wil een eerste indruk van de vergoeding zonder ingewikkelde berekening. Wat is het renteverlies van de geldverstrekker zonder contantmaking?", [["€ 2.000", "€ 50.000 × 1% × 4 jaar = € 2.000; na contantmaking valt de werkelijke vergoeding iets lager uit."], ["€ 500", "Dit is het renteverlies van één jaar; er resteren nog vier jaar."], ["€ 5.000", "Dit rekent met tien jaar in plaats van de resterende vier jaar."], ["€ 200", "Dit rekent met 0,1% in plaats van het renteverschil van 1 procentpunt."]], "1e.10"],
["Waarom wordt het renteverlies bij de berekening van de vergoeding voor vervroegde aflossing contant gemaakt?", [["Omdat het renteverlies in de toekomst ligt en nu in één keer wordt betaald", "Een toekomstig verlies is vandaag minder waard; contantmaking voorkomt dat de klant meer betaalt dan het werkelijke nadeel."], ["Omdat de vergoeding altijd contant bij de notaris moet worden betaald", "Contant maken is een rekenmethode, geen betaalwijze met contant geld."], ["Omdat de vergoeding anders onder de Wwft-meldplicht valt", "De Wwft heeft niets te maken met de berekeningsmethode van de vergoeding."], ["Omdat de vergoeding hierdoor fiscaal aftrekbaar wordt", "De fiscale behandeling hangt niet af van contantmaking."]], "1e.10"],
["Wendy (44) en Marco (46) hebben een hypotheek van € 250.000 tegen 4,9%, die nog zeven jaar vaststaat. De huidige rente voor zeven jaar vast is duidelijk lager. Oversluiten kost hen een vergoeding wegens vervroegde aflossing plus advies-, taxatie- en notariskosten. Zij vragen of het de moeite waard is. Wanneer is tussentijds oversluiten financieel zinvol?", [["Als het netto rentevoordeel groter is dan de vergoeding en alle bijkomende kosten", "Oversluiten loont pas als het netto voordeel (na belastingeffect) de vergoeding en de kosten overtreft."], ["Altijd, omdat een lagere rente op de lange termijn hoe dan ook voordeliger is", "De vergoeding en kosten kunnen het rentevoordeel tenietdoen."], ["Alleen als de nieuwe rentevaste periode korter is dan hun oude periode", "De lengte van de nieuwe periode bepaalt niet of oversluiten loont."], ["Alleen als zij de vergoeding uit eigen spaargeld kunnen betalen", "De vergoeding kan onder voorwaarden ook worden meegefinancierd; het gaat om het saldo van voordeel en kosten."]], "3e.3"],
["Een verkoper heeft een hypotheek met een doorgeefregeling. Wat houdt die regeling in?", [["De koper kan de hypotheek met rente en voorwaarden overnemen, mits de geldverstrekker hem accepteert", "De lening gaat over op de koper; de geldverstrekker toetst wel of de koper kredietwaardig is."], ["De verkoper mag zijn rente meenemen naar zijn eigen nieuwe woning", "Dat is de meeneem- of verhuisregeling, niet de doorgeefregeling."], ["De koper krijgt automatisch dezelfde hypotheek als de verkoper, zonder toetsing door de geldverstrekker", "De geldverstrekker blijft de kredietwaardigheid van de nieuwe schuldenaar beoordelen."], ["De verkoper kan zijn vergoeding wegens vervroegde aflossing doorberekenen aan de koper", "Een doorgeefregeling gaat over het overnemen van de lening, niet over het doorschuiven van een vergoeding."]], "1h.6"],
["Een klant financiert zonnepanelen en een warmtepomp met een extra leningdeel. Waarom is het verstandig de looptijd van dat leningdeel af te stemmen op de levensduur van de installaties?", [["Zodat de lening is afgelost voordat de installaties versleten zijn en vervangen moeten worden", "Anders betaalt de klant nog af op installaties die al vervangen moeten worden, terwijl er een nieuwe investering bij komt."], ["Omdat een lening voor duurzame installaties volgens de wet nooit langer mag lopen dan tien jaar", "Zo'n wettelijke maximale looptijd bestaat niet; het gaat om verstandig financieren."], ["Omdat de renteaftrek vervalt zodra de installaties zijn afgeschreven", "De renteaftrek hangt af van de regels voor eigenwoningschuld, niet van afschrijving."], ["Omdat de geldverstrekker de installaties anders aan het einde mag weghalen", "De geldverstrekker heeft een hypotheekrecht op de woning en geen recht om installaties weg te halen."]], "1i.1"],
["Wat moet een hypotheekadviseur een klant vóór de dienstverlening verstrekken over zijn diensten en kosten?", [["De aard van de dienstverlening en de kosten", "De klant moet vooraf weten wat de adviseur doet, voor wie en wat het kost, om een bewuste keuze te maken."], ["Niets, kosten worden pas na afloop met de factuur gemeld", "Kosteninformatie moet juist vooraf worden gegeven, zodat de klant weet waar hij aan toe is."], ["Alleen het ESIS van de geldverstrekker", "Het ESIS gaat over het krediet, niet over de diensten en kosten van de adviseur."], ["Een overzicht van de provisie die hij van de geldverstrekker ontvangt", "Voor hypotheken geldt een provisieverbod; de klant betaalt de adviseur rechtstreeks."]], "1a.6"],
["Over welk diploma moet een adviseur die consumenten adviseert over hypothecair krediet in elk geval beschikken?", [["Het Wft-diploma Hypothecair Krediet", "Vakbekwaamheid vereist het passende Wft-diploma en het actueel houden van kennis via PE."], ["Een registratie als taxateur in het NRVT", "Een taxateur-registratie gaat over het waarderen van woningen, niet over hypotheekadvies."], ["Een notarieel getuigschrift", "Notarissen hebben een eigen opleiding; die is geen vakbekwaamheidseis voor adviseurs."], ["Alleen het Wft-diploma Basis is voldoende", "Basis is een onderdeel, maar voor hypotheekadvies is ook het diploma Hypothecair Krediet vereist."]], "1b.4"],
["Een klant is ontevreden over het hypotheekadvies en komt er met zijn adviseur niet uit. Waar kan hij met een klacht terecht?", [["Bij Kifid", "Een Wft-adviseur moet zijn aangesloten bij een erkende geschilleninstantie; voor financiële diensten is dat Kifid."], ["Bij FIU-Nederland", "FIU-Nederland ontvangt meldingen van ongebruikelijke transacties, geen klachten van consumenten."], ["Bij het Kadaster", "Het Kadaster houdt registers bij en behandelt geen klachten over advies."], ["Bij de Stichting WEW", "De Stichting WEW verstrekt NHG; zij beslist niet over geschillen tussen klant en adviseur."]], "1a.3"],
["Mag een consument een hypotheek afsluiten zonder advies (execution only)?", [["Ja, maar de kredietwaardigheidstoets blijft gelden", "Ook zonder advies blijft de verplichting om overkreditering te voorkomen bij de kredietgever liggen."], ["Nee, hypotheekadvies is voor consumenten wettelijk verplicht", "De wet verplicht niet tot advies; een consument mag zonder advies kiezen."], ["Ja, en dan vervalt ook de kredietwaardigheidstoets", "De toets geldt altijd, met of zonder advies."], ["Alleen als de hypotheek met NHG wordt afgesloten", "Execution only hangt niet af van NHG."]], "1b.4"],
["Een werknemer ontvangt jaarlijks een vaste, onvoorwaardelijke dertiende maand. Hoe telt die mee in het toetsinkomen?", [["Die telt volledig mee als vast inkomen", "Vaste en onvoorwaardelijke componenten zoals een vaste eindejaarsuitkering horen bij het structurele inkomen."], ["Die telt niet mee, omdat hij maar eenmaal per jaar wordt uitbetaald", "Het moment van uitbetaling is niet bepalend; ook vakantiegeld wordt eenmaal per jaar betaald en telt mee."], ["Die telt alleen mee als de werkgever er een bonusreglement voor heeft", "Een vaste dertiende maand is geen bonus; een reglement is niet nodig als zij onvoorwaardelijk is."], ["Die telt mee, maar alleen voor de helft", "Een halvering kent de toets niet; een vast inkomensbestanddeel telt volledig mee."]], "2c.2"],
["Niels (39) werkt als verkoopleider bij een groothandel in Venlo. Naast zijn vaste salaris van € 58.000 kreeg hij de afgelopen jaren een prestatiebonus, die elk jaar opnieuw wordt vastgesteld en niet gegarandeerd is. Hij wil verhuizen naar een grotere woning en hoopt dat de bonus meetelt. Op zijn werkgeversverklaring staat de bonus als variabel. Hoe gaan geldverstrekkers daar meestal mee om?", [["Een variabele, niet-gegarandeerde bonus telt in beginsel niet mee als vast inkomen", "Alleen vaste en structurele inkomensbestanddelen tellen in beginsel mee; een onzekere bonus niet."], ["De bonus telt volledig mee, omdat hij de afgelopen jaren steeds is uitbetaald", "Uitbetaling in het verleden geeft geen zekerheid voor de toekomst."], ["De bonus telt dubbel mee om de onzekerheid van zijn salaris op te vangen", "Dubbel meetellen bestaat niet en zou het risico juist vergroten."], ["De bonus verlaagt zijn toetsinkomen, omdat hij er meer belasting over betaalt", "De belasting over een bonus verlaagt het bruto toetsinkomen niet."]], "2c.2"],
["Bij een gepensioneerde aanvrager: wat vormt in de regel het toetsinkomen?", [["De AOW-uitkering en de pensioenuitkeringen", "Na de AOW-leeftijd bestaat het structurele inkomen uit AOW en (aanvullend) pensioen; daarvoor gelden aparte percentages."], ["Het laatstverdiende salaris vóór pensionering", "Dat salaris is er niet meer; de toets kijkt naar het huidige structurele inkomen."], ["Het vermogen in box 3 gedeeld door dertig", "Vermogen kan in het advies meewegen, maar is niet het standaard toetsinkomen."], ["Alleen het aanvullend pensioen, zonder AOW", "De AOW is een vast basisinkomen en telt mee in het toetsinkomen."]], "1i.4"],
["Een klant heeft een vast contract met een proeftijd die nog loopt. Waarom is dit relevant voor de hypotheekaanvraag?", [["Het dienstverband kan dan eenvoudig worden beëindigd", "Veel geldverstrekkers willen dat de proeftijd voorbij is of vragen een aanvullende verklaring van de werkgever."], ["Tijdens de proeftijd is het salaris belastingvrij", "Ook tijdens de proeftijd wordt over het salaris loonbelasting ingehouden."], ["Een proeftijd betekent dat het contract tijdelijk is", "Een vast contract blijft een vast contract, ook met een proeftijd."], ["Tijdens de proeftijd telt alleen het netto salaris mee", "De toets rekent met bruto inkomen; de proeftijd verandert dat niet."]], "2c.2"],
["Hoe telt een studieschuld bij DUO sinds 2024 mee in de leennormen?", [["Op basis van de werkelijke maandlast van de studieschuld", "De TRHK weegt sinds 2024 de actuele maandelijkse aflossing mee in plaats van een percentage van de oorspronkelijke schuld."], ["Op basis van een vast percentage van de oorspronkelijke studieschuld", "Dat was de methode tot 2024; nu is de werkelijke maandlast het uitgangspunt."], ["Niet, omdat DUO-schulden niet bij het BKR geregistreerd staan", "Ook al staat zij niet bij het BKR, de studieschuld telt wel mee; de klant moet haar opgeven."], ["Alleen als de klant een achterstand bij DUO heeft", "Ook zonder achterstand is de studieschuld een verplichting die meeweegt."]], "1i.4"],
["Een ongehuwd samenwonende klant zonder kinderen overlijdt. Waarom kan zijn partner dan in de regel niet rekenen op een Anw-uitkering?", [["Alleen bij een kind onder 18 of eigen arbeidsongeschiktheid", "Zonder jong kind of arbeidsongeschiktheid heeft een partner, geboren na 1949, geen recht op Anw."], ["De Anw geldt alleen voor gehuwde partners", "Ook samenwonenden met een gezamenlijke huishouding kunnen recht hebben; de voorwaarden zitten in kinderen en arbeidsongeschiktheid."], ["De Anw wordt alleen uitgekeerd als er een hypotheek met NHG is", "De Anw is een volksverzekering en staat los van de hypotheek."], ["De Anw-uitkering gaat altijd rechtstreeks naar de geldverstrekker", "De Anw wordt aan de nabestaande zelf betaald, als er recht op is."]], "1a.4"],
["Jordy (32) en Anna (30) wonen ongehuwd samen en kopen een woning in Enschede. Ieder verdient ongeveer de helft van het gezinsinkomen. Zij willen allebei het leven van de ander verzekeren met een overlijdensrisicoverzekering. Hun adviseur raadt aan de polissen kruislings af te sluiten. Waarom adviseert hij dat?", [["Zodat er bij overlijden geen erfbelasting over de uitkering wordt geheven", "Als de partner zelf verzekeringnemer is, de premie betaalt en begunstigde is, valt de uitkering niet onder de erfbelasting."], ["Zodat de premie van beide polissen aftrekbaar wordt in box 1", "De premie van een overlijdensrisicoverzekering is niet aftrekbaar, ook niet kruislings."], ["Zodat beide partners een uitkering ontvangen bij één overlijden", "Bij één overlijden keert alleen de polis op het leven van de overledene uit."], ["Zodat de uitkering via de notaris automatisch de hypotheek aflost", "Kruislings verzekeren regelt de belasting, niet de aflossing via de notaris."]], "1i.6"],
["Hamza (35) en Lieke (34) sluiten een annuïteitenhypotheek van € 320.000 af voor hun eerste woning in Den Bosch. Lieke verdient het grootste deel van het inkomen. Zij willen dat Hamza bij overlijden van Lieke de woning kan blijven betalen. Zij willen geen premie betalen voor dekking die zij later niet meer nodig hebben. Welke dekkingsvorm van de overlijdensrisicoverzekering sluit het best aan bij het verloop van hun schuld?", [["Een annuïtair dalende dekking, die meedaalt met hun resterende schuld", "Bij een annuïteitenhypotheek daalt de schuld eerst langzaam en later sneller; een annuïtair dalende dekking volgt dat verloop."], ["Een gelijkblijvende dekking van € 320.000 over de hele looptijd", "Een gelijkblijvende dekking is duurder en loopt steeds verder voor op de dalende schuld."], ["Een lineair dalende dekking die in het begin juist snel daalt", "Lineair dalen past bij een lineaire hypotheek; bij een annuïteit zou de dekking in het begin te snel dalen."], ["Een stijgende dekking die met de inflatie meegroeit", "De schuld stijgt niet, dus een stijgende dekking past niet bij het schuldverloop."]], "1g.2"],
["Wat wordt bedoeld met het WGA-gat bij arbeidsongeschiktheid?", [["Een inkomensterugval na de loongerelateerde WGA-uitkering", "Wie zijn restverdiencapaciteit onvoldoende benut, valt terug op een uitkering op basis van het minimumloon, wat de woonlasten kan bedreigen."], ["De periode van twee jaar loondoorbetaling door de werkgever", "Loondoorbetaling gaat vooraf aan de WIA en is geen gat in het inkomen."], ["Het verschil tussen bruto en netto WGA-uitkering", "Dat is een gewoon belastingeffect, niet wat met het WGA-gat bedoeld wordt."], ["Het deel van het salaris boven het maximumdagloon", "Dat is het WIA-excedent, een ander risico dan het WGA-gat."]], "1a.4"],
["Een werknemer wordt werkloos en krijgt WW. Welk percentage van het (gemaximeerde) dagloon ontvangt hij?", [["De eerste twee maanden 75%, daarna 70%", "De WW start met 75% en daalt na twee maanden naar 70% van het dagloon, tot het maximumdagloon."], ["De hele duur 100% van het laatstverdiende loon", "De WW vervangt het loon slechts gedeeltelijk; volledige vervanging bestaat niet."], ["De eerste twee maanden 70%, daarna 75%", "De volgorde is andersom: de uitkering daalt na twee maanden."], ["Steeds 50%, ongeacht de duur", "Het percentage ligt hoger en verandert na twee maanden."]], "1a.4"],
["Welke verzekering keert maandelijks een bedrag uit om de woonlasten te betalen als de klant arbeidsongeschikt of werkloos wordt?", [["Een woonlastenverzekering", "Deze dekt de maandlasten voor een beperkte periode bij arbeidsongeschiktheid en/of werkloosheid."], ["Een opstalverzekering", "Een opstalverzekering dekt schade aan de woning, niet inkomensverlies."], ["Een overlijdensrisicoverzekering", "Een ORV keert alleen uit bij overlijden van de verzekerde."], ["Een rechtsbijstandsverzekering", "Rechtsbijstand helpt bij juridische geschillen, niet bij het betalen van de maandlasten."]], "1g.1"],
["Een klant koopt een woning met een hypotheek van 100% van de marktwaarde. Een paar jaar later dalen de huizenprijzen. Welk risico ontstaat?", [["Bij verkoop kan een restschuld ontstaan", "Bij onderwaarde dekt de verkoopopbrengst de schuld niet; dat beperkt ook de mogelijkheid om te verhuizen."], ["De rente wordt automatisch verhoogd tot het niveau van een consumptief krediet", "Een waardedaling leidt niet automatisch tot een consumptieve rente; hooguit kan een risico-opslag later hoger uitvallen."], ["De hypotheek wordt direct opeisbaar", "Een prijsdaling is geen opeisingsgrond zolang de klant aan zijn betalingen voldoet."], ["De renteaftrek vervalt, omdat de lening hoger is dan de woningwaarde", "Een waardedaling heeft geen invloed op de fiscale status van de eigenwoningschuld."]], "1e.9"],
["Jolanda (49) en Frank (51) hebben een nieuwe woning in Amersfoort gekocht, die over drie maanden wordt geleverd. Hun huidige woning in Leusden staat sinds kort te koop, maar er is nog geen koper. Zij willen de nieuwe woning toch kopen, omdat die precies past. De bank is bereid beide hypotheken een tijd naast elkaar te laten lopen. Welk risico hoort de adviseur in elk geval met hen te bespreken?", [["Dubbele woonlasten zolang de oude woning nog niet is verkocht", "Zolang de oude woning niet is verkocht, betalen zij twee keer woonlasten; de adviseur moet nagaan of zij dat kunnen dragen."], ["Het verlies van hun recht op NHG voor de nieuwe woning", "Een onverkochte oude woning sluit NHG voor de nieuwe woning niet automatisch uit."], ["Een hogere overdrachtsbelasting over de oude woning", "De verkoper betaalt geen overdrachtsbelasting; die is voor de koper."], ["Het vervallen van de wettelijke bedenktijd voor de nieuwe woning", "De bedenktijd staat los van de verkoop van de oude woning."]], "1e.11"],
["Waarom verdient funderingsrisico aandacht in het hypotheekadvies, bijvoorbeeld bij oudere woningen in veengebieden?", [["Herstel kan duur zijn en de waarde van de woning raken", "Funderingsproblemen kunnen tot hoge herstelkosten, waardedaling en problemen bij herfinanciering leiden."], ["Het verlaagt automatisch de hypotheekrente via de risicoklasse", "Funderingsrisico leidt niet tot een lagere rente; het vergroot juist het risico."], ["Het bepaalt de hoogte van de landelijke NHG-kostengrens", "De NHG-kostengrens is landelijk vastgesteld en staat los van individuele woningen."], ["Het is alleen relevant voor nieuwbouwwoningen", "Funderingsproblemen spelen juist bij oudere woningen met houten palen of op staal."]], "1f.1"],
["Stijn (35) is leraar en koopt alleen een appartement in Zwolle met een volledig annuïtaire hypotheek. Hij heeft al zijn spaargeld gebruikt voor de kosten koper en de inrichting. Zijn auto is oud en zijn cv-ketel moet binnenkort worden vervangen. Hij gaat ervan uit dat hij onverwachte kosten wel uit zijn salaris kan betalen. Wat is een belangrijk aandachtspunt in het advies?", [["Het belang van het opbouwen van een financiële buffer voor onverwachte uitgaven", "Zonder buffer kan een tegenvaller direct tot betalingsproblemen leiden; de adviseur hoort dit te bespreken."], ["Dat hij de hypotheek beter aflossingsvrij kan maken om sneller vermogen op te bouwen", "Een aflossingsvrije lening is geen eigenwoningschuld en verhoogt het risico aan het einde."], ["Dat zijn renteaftrek na tien jaar vervalt en zijn lasten dan stijgen", "De renteaftrek loopt maximaal dertig jaar, niet tien jaar."], ["Dat hij naast de hypotheek verplicht een beleggingsverzekering moet afsluiten", "Een beleggingsverzekering is nooit verplicht naast een annuïteitenhypotheek."]], "1d.2"],
["Adviseur Pieter adviseerde Marco (40) en Ilona (38) in 2011 een volledig aflossingsvrije hypotheek. In zijn dossier staat niet dat hij de risico's daarvan met hen heeft besproken. Nu blijkt dat zij de schuld bij het einde van de looptijd niet kunnen herfinancieren, en zij dienen een klacht in bij Kifid. Zij stellen dat zij nooit op de risico's zijn gewezen. Wat weegt bij de beoordeling van Pieters aansprakelijkheid zwaar?", [["Of Pieter kan aantonen dat hij de risico's besprak; zonder vastlegging is dat lastig", "De adviseur moet zijn zorgplicht kunnen aantonen; een onvolledig dossier komt meestal voor zijn rekening."], ["Alleen of de geldverstrekker de hypotheek destijds heeft goedgekeurd", "Acceptatie door de geldverstrekker ontslaat de adviseur niet van zijn eigen zorgplicht."], ["Of de klanten het adviesrapport hebben ondertekend, ongeacht de inhoud ervan", "Een handtekening zegt weinig als niet blijkt dat de risico's begrijpelijk zijn uitgelegd."], ["Niets, want de klant is na het tekenen van de offerte zelf verantwoordelijk", "De adviseur blijft verantwoordelijk voor de kwaliteit van zijn advies."]], "1c.1"],
["Waarom moet een hypotheekadviseur de risicobereidheid van de klant goed in kaart brengen?", [["Omdat die mede bepaalt welke rentevaste periode, aflossingsvorm en verzekeringen passen", "Een passend advies sluit aan bij de mate waarin de klant financiële risico's wil en kan dragen."], ["Omdat de geldverstrekker de rente afstemt op de risicobereidheid van de klant", "De rente hangt af van onder meer de rentevaste periode en de LTV, niet van de risicohouding."], ["Omdat een klant met weinig risicobereidheid wettelijk minder mag lenen", "Zo'n wettelijke norm bestaat niet; de leennormen gaan uit van inkomen en woningwaarde."], ["Omdat de risicobereidheid de hoogte van het toetsinkomen bepaalt", "Het toetsinkomen volgt uit het inkomen, niet uit de risicohouding."]], "1d.1"],
["Adviseur Monique begeleidt Dewi (29), die een appartement in Utrecht wil kopen. Dewi levert een werkgeversverklaring aan met een salaris van € 62.000, maar op haar salarisstroken en in de UWV-gegevens staat een duidelijk lager bedrag. De handtekening op de verklaring lijkt bovendien op die van Dewi zelf. Dewi wil de aanvraag snel indienen. Wat hoort Monique te doen?", [["De aanvraag niet zo indienen, de afwijking onderzoeken en het signaal volgens de fraudeprocedure melden", "Een mogelijk vervalst stuk is een fraudesignaal dat de adviseur zelf moet opvolgen; zij mag het niet ongezien doorsturen."], ["De aanvraag gewoon indienen, omdat de geldverstrekker zelf verantwoordelijk is voor de controle van stukken", "De adviseur heeft een eigen verantwoordelijkheid; bewust indienen van mogelijk valse stukken is niet toegestaan."], ["Het salaris op de werkgeversverklaring zelf aanpassen naar het lagere bedrag", "Een adviseur mag stukken van de klant of werkgever nooit zelf wijzigen."], ["De aanvraag indienen met alleen de salarisstroken en de verklaring achterhouden", "Achterhouden lost het fraudesignaal niet op; het signaal moet worden opgevolgd."]], "4a.1"],
["Een klant met een eigen bv wil een hypotheek en overweegt geld uit zijn bv te lenen en dividend uit te keren. De adviseur heeft weinig kennis van de fiscale regels voor een bv. Wat is de juiste houding?", [["Een fiscaal specialist inschakelen of doorverwijzen voor het deel dat buiten zijn deskundigheid valt", "Een adviseur kent de grenzen van zijn kennis en verwijst door als dat in het belang van de klant is."], ["Zelf een inschatting maken, omdat hij met zijn Wft-diploma Hypothecair Krediet ook fiscaal mag adviseren", "Het diploma dekt geen specialistische fiscale vragen over een bv; adviseren buiten zijn deskundigheid schaadt de klant."], ["De fiscale vragen buiten het advies laten zonder dit met de klant te bespreken", "De klant moet weten welk deel niet is onderzocht en waar hij terecht kan."], ["De klant aanraden geen hypotheek af te sluiten zolang hij een bv heeft", "Een bv is geen beletsel voor een hypotheek; het vraagt alleen specialistische kennis."]], "4a.2"],
["Een klant wil een warmtepomp laten plaatsen, die hij met zijn hypotheek financiert. Hoe kan het leningdeel fiscaal worden behandeld?", [["Als eigenwoningschuld, want het verbetert de woning", "Uitgaven voor verbetering van de eigen woning kunnen eigenwoningschuld zijn als aan de aflossingseis wordt voldaan."], ["Als box 3-schuld, omdat een warmtepomp een roerende zaak is", "Een vast aangebrachte installatie verbetert de woning en kan in de eigenwoningschuld vallen."], ["Als consumptief krediet zonder fiscale gevolgen", "Financiering via de hypotheek voor woningverbetering kan juist wel eigenwoningschuld zijn."], ["De rente is dubbel aftrekbaar vanwege de duurzaamheid", "Er bestaat geen dubbele aftrek voor duurzame investeringen."]], "1a.1"],
["Een klant neemt een hypotheek in een vreemde valuta. Wat regelt de hypothekenrichtlijn (MCD) hierover?", [["Waarborgen tegen wisselkoersrisico, zoals omzetting", "Valutaleningen kunnen bij koersschommelingen sterk duurder worden; de MCD vereist daarom waarborgen."], ["Valutaleningen zijn in de hele EU verboden", "De MCD verbiedt ze niet, maar stelt eisen aan bescherming en informatie."], ["De geldverstrekker draagt altijd zelf het volledige koersverlies", "Het risico ligt in beginsel bij de consument; de MCD beperkt dat met waarborgen."], ["Valutaleningen vallen buiten de richtlijn", "Ze vallen er juist onder, met extra regels."]], "1a.3"],
["Wat verwacht de hypothekenrichtlijn (MCD) van kredietgevers als een consument betalingsachterstanden heeft?", [["Redelijke clementie en pogingen tot een oplossing vóór executie", "De richtlijn vraagt aanbieders eerst te zoeken naar oplossingen, zoals een betalingsregeling, voordat ze executeren."], ["Direct executeren om verdere achterstanden te voorkomen", "Onmiddellijk executeren is in strijd met de gedachte van clementie in de richtlijn."], ["De rente verdubbelen tot de achterstand is ingelopen", "Een strafrente verdubbelen helpt de consument niet en past niet bij de richtlijn."], ["De achterstand melden bij FIU-Nederland", "Een betalingsachterstand is geen ongebruikelijke transactie in de zin van de Wwft."]], "1j.2"],
["Wanneer mag een hypotheekadviseur zich 'onafhankelijk' noemen?", [["Als hij ruim vergelijkt en geen beloning van aanbieders ontvangt", "Deze eis komt uit de hypothekenrichtlijn: onafhankelijkheid vereist een ruime marktvergelijking en geen beloning van aanbieders."], ["Als hij bij geen enkele geldverstrekker in dienst is", "Niet in dienst zijn is niet genoeg; hij moet ook voldoende producten vergelijken."], ["Als hij een bord 'onafhankelijk' aan de gevel van zijn kantoor heeft", "De term is wettelijk beschermd en vraagt meer dan een eigen verklaring."], ["Als hij alleen met de drie grootste banken werkt", "Drie aanbieders is geen voldoende aantal producten voor een ruime marktvergelijking."]], "1b.4"],
["Een reclame voor hypotheken noemt een rentepercentage. Wat vereisen de regels op grond van de hypothekenrichtlijn?", [["Standaardinformatie met een representatief voorbeeld", "Wie in reclame rente of kosten noemt, moet ook informatie geven zoals het JKP met een representatief voorbeeld."], ["Dat de AFM de reclame vooraf heeft goedgekeurd", "De AFM keurt reclame niet vooraf goed; zij houdt achteraf toezicht."], ["Dat het rentepercentage minimaal een jaar geldig blijft", "Zo'n eis bestaat niet voor reclame."], ["Dat de reclame alleen online mag verschijnen", "Er is geen beperking tot online reclame."]], "1a.3"],
["Rachid (42) en Hanna (40) zijn verhuisd naar hun nieuwe woning in Leiden. Hun vorige woning in Den Haag staat al een jaar te koop. Om de dubbele lasten te beperken, verhuren zij die tijdelijk met een vergunning op grond van de Leegstandwet en met toestemming van de geldverstrekker. De huur dekt een groot deel van de rente. Wat is het fiscale gevolg voor de periode van verhuur?", [["In die periode valt de oude woning met de bijbehorende schuld in box 3, niet in box 1", "Een verhuurde woning is geen leegstaande eigen woning meer; tijdens de verhuur vallen woning en schuld in box 3."], ["De rente blijft volledig aftrekbaar, omdat de woning nog steeds te koop staat", "De regeling voor leegstaande woningen geldt niet als de woning wordt verhuurd."], ["De huurinkomsten worden belast in box 1 en de rente blijft daar aftrekbaar", "Verhuur valt niet onder de eigenwoningregeling in box 1."], ["De woning valt in box 2, omdat zij inkomsten uit verhuur oplevert", "Box 2 gaat over een aanmerkelijk belang in een vennootschap, niet over verhuur van een woning."]], "1e.11"],
["Joyce (33) en Ramon (35) krijgen het advies om een rentevaste periode van twintig jaar te kiezen, omdat zij weinig financiële ruimte hebben. Ramon wil toch een variabele rente, omdat die nu lager is. De adviseur legt de risico's van een rentestijging uit, maar zij blijven bij hun keuze. Zij willen de aanvraag zo doorzetten. Wat hoort de adviseur te doen?", [["De gevolgen nogmaals toelichten en de afwijking van zijn advies met hun motivering vastleggen", "Een klant mag afwijken van het advies; de adviseur legt dan vast dat en waarom de klant afwijkt en welke gevolgen zijn besproken."], ["Zijn advies aanpassen zodat het precies aansluit bij de keuze van Ramon", "Het advies moet passend blijven; het aanpassen aan de klantwens zonder onderbouwing is geen echt advies."], ["Weigeren de aanvraag verder te begeleiden, omdat afwijken van een advies wettelijk niet is toegestaan", "Afwijken van het advies is toegestaan; de wet verbiedt dat niet."], ["De keuze uitvoeren zonder iets vast te leggen, omdat de klant zelf heeft beslist", "Juist bij afwijken is vastlegging in het dossier belangrijk."]], "3c.4"],
["Een klant die een hypotheek aanvraagt, blijkt een politiek prominent persoon (PEP) te zijn. Wat geldt?", [["Verscherpt cliëntenonderzoek, onder meer naar de herkomst van het vermogen", "Bij een PEP is het risico op corruptie hoger; de instelling moet extra maatregelen nemen."], ["De aanvraag moet worden geweigerd", "Dienstverlening aan een PEP is toegestaan, mits met verscherpte maatregelen."], ["Vereenvoudigd cliëntenonderzoek is voldoende", "Een PEP brengt juist een hoger risico mee, dus vereenvoudigd onderzoek past niet."], ["Er is geen cliëntenonderzoek nodig vanwege de publieke functie", "Een publieke functie verkleint het risico niet; cliëntenonderzoek blijft verplicht."]], "1a.3"],
["Wouter (37) en Kirsten (36) hebben een bindend hypotheekaanbod voor een woning in Alkmaar en de overdracht is over vier weken. Wouter hoort van zijn werkgever dat zijn functie vervalt en dat hij over drie maanden wordt ontslagen. De aanvraag is gebaseerd op zijn huidige inkomen. Zij vragen hun adviseur of zij dit moeten melden. Wat is juist?", [["Het ontslag melden aan de geldverstrekker, omdat het aanbod op het huidige inkomen is gebaseerd", "Een wezenlijke wijziging tijdens het aanvraagtraject moet worden gemeld; de geldverstrekker beoordeelt dan opnieuw en de adviseur bespreekt de gevolgen."], ["Niets melden, omdat het aanbod al bindend is en de geldverstrekker het niet meer mag intrekken", "Verzwijgen van een wezenlijke wijziging is in strijd met de voorwaarden van het aanbod en met de zorgplicht."], ["Alleen melden als het ontslag na de overdracht nog niet is ingetrokken", "Wachten tot na de overdracht ontneemt de geldverstrekker de kans om de wijziging te beoordelen."], ["De koop direct ontbinden met een beroep op de wettelijke bedenktijd", "De bedenktijd van drie dagen is allang verstreken en staat los van een ontslag."]], "2e.3"],
["Linda (46) is alleenstaand en werkt als winkelmanager in Purmerend. Door een lange ziekte en een tijdelijk lager inkomen loopt zij twee maanden achter met haar hypotheekbetalingen. Zij schaamt zich en heeft brieven van de bank ongeopend laten liggen. Zij vraagt haar adviseur wat zij nu moet doen. Wat is het beste advies?", [["Zo snel mogelijk contact opnemen met de geldverstrekker om een (tijdelijke) oplossing te bespreken", "Hoe eerder de klant contact opneemt, hoe meer mogelijkheden er zijn, zoals een betalingsregeling; zo wordt verdere escalatie voorkomen."], ["Afwachten tot de bank zelf met een oplossing komt, omdat die wettelijk verplicht is om haar te helpen", "Afwachten vergroot de achterstand en de kans op verdere maatregelen."], ["Snel een persoonlijke lening afsluiten om de achterstand in één keer in te lopen", "Nieuwe schulden maken het probleem meestal groter."], ["De woning direct te koop zetten om executie door de bank te voorkomen", "Verkoop is pas aan de orde als andere oplossingen niet werken; eerst moet het gesprek met de bank plaatsvinden."]], "3f.1"],
["Iris (27) en Joep (28) huren een appartement in Utrecht en twijfelen of zij een woning zullen kopen. Joep verwacht over twee à drie jaar voor zijn werk naar het buitenland te verhuizen. Zij hebben weinig spaargeld en moeten de kosten koper grotendeels zelf betalen. Een vriend zegt dat kopen altijd beter is dan huren. Wat is in hun situatie een belangrijke overweging?", [["De verwachte woonduur, omdat de eenmalige aankoopkosten bij een korte woonduur zwaar drukken", "Kosten koper en verkoopkosten worden pas over een langere periode terugverdiend; bij een korte woonduur kan huren gunstiger zijn."], ["Kopen is altijd voordeliger, omdat huur weggegooid geld is", "Of kopen voordeliger is, hangt af van woonduur, kosten, rente en prijsontwikkeling."], ["Huren is altijd voordeliger, omdat een huurder geen onderhoud betaalt", "Ook huren is niet altijd voordeliger; de afweging hangt af van de situatie."], ["De hoogte van de huurtoeslag die zij na de aankoop van een eigen woning nog blijven ontvangen", "Na aankoop van een woning bestaat geen recht op huurtoeslag."]], "1b.1"],
["Wat moet een financiële onderneming naast de Wwft controleren op grond van de Sanctiewet 1977?", [["Of klanten op sanctielijsten staan", "Bij een treffer moeten tegoeden worden bevroren en mag geen dienstverlening plaatsvinden."], ["Of klanten een Verklaring Omtrent het Gedrag hebben", "Een VOG vraagt de werkgever van medewerkers, niet van klanten."], ["Of klanten een BKR-registratie hebben", "BKR-toetsing hoort bij kredietverlening, niet bij de Sanctiewet."], ["Of klanten een testament hebben opgesteld", "Dat is geen onderdeel van de Sanctiewet."]], "1a.3"],
["Een klant wil voor de hypotheekaanvraag geen identiteitsbewijs laten zien. Wat moet de Wwft-instelling doen?", [["De zakelijke relatie niet aangaan en de aanvraag niet verwerken", "Zonder vastgestelde en geverifieerde identiteit mag de instelling geen relatie aangaan en moet zij overwegen te melden."], ["De aanvraag verwerken en de identificatie later inhalen", "Identificatie moet in beginsel vooraf plaatsvinden; zonder kan de relatie niet starten."], ["Volstaan met een kopie van een energierekening", "Een energierekening bewijst geen identiteit."], ["De klant doorverwijzen naar de notaris, die de identificatie overneemt", "De instelling moet zelf aan haar plicht voldoen."]], "1a.3"],
["Ger (55) en Petra (53) wonen in hun eigen woning in Zeist. Hun dochter Romy (19) gaat in Utrecht studeren en zij kopen voor haar een klein appartement. Romy gaat er wonen; Ger en Petra blijven zelf in hun eigen huis. Zij staan als enige kopers op de koopakte. Welk tarief overdrachtsbelasting geldt voor Ger en Petra?", [["Het hogere tarief, omdat zij de woning niet zelf als hoofdverblijf gaan bewonen", "Het verlaagde tarief en de startersvrijstelling gelden alleen voor een koper die de woning zelf als hoofdverblijf gaat bewonen."], ["Het verlaagde tarief, omdat een familielid van hen in de woning gaat wonen", "Bewoning door een kind telt niet als eigen bewoning door de koper."], ["De startersvrijstelling, omdat Romy jonger is dan 35 jaar", "De vrijstelling wordt beoordeeld bij de koper, niet bij de bewoner."], ["Geen overdrachtsbelasting, omdat het om studentenhuisvesting gaat", "Er bestaat geen vrijstelling voor studentenhuisvesting door ouders."]], "1a.1"],
["Een klant heeft een overbruggingskrediet op zijn oude woning, die langer te koop staat dan verwacht. Wat is een belangrijk risico?", [["De overbrugging loopt af voordat de oude woning is verkocht", "Overbruggingskredieten hebben een beperkte looptijd; blijft verkoop uit, dan lopen lasten en onzekerheid op."], ["De overbrugging wordt automatisch omgezet in een starterslening", "Een starterslening is een aparte regeling en ontstaat niet uit een overbrugging."], ["De renteaftrek op de nieuwe woning vervalt direct", "De aftrek voor de nieuwe woning blijft gewoon bestaan."], ["De nieuwe woning moet worden teruggegeven aan de verkoper", "De koop van de nieuwe woning staat vast; een trage verkoop maakt die niet ongedaan."]], "1e.3"],
["Een klant vraagt of de geldverstrekker zijn hypotheekrente mag verhogen tijdens een lopende rentevaste periode. Wat is in beginsel juist?", [["Nee, tijdens de rentevaste periode staat de afgesproken rente vast", "Dat is precies de zekerheid die de klant met een rentevaste periode koopt."], ["Ja, als de marktrente stijgt mag de bank de rente direct aanpassen", "Dat geldt bij een variabele rente, niet bij een vaste rente."], ["Ja, maar alleen eenmaal per jaar met maximaal één procentpunt", "Zo'n regel bestaat niet voor vaste rentes."], ["Ja, als de AFM-toetsrente stijgt", "De toetsrente is een toetsingscijfer en verandert de contractrente niet."]], "1e.2"],
["Een klant heeft twee leningdelen: een annuïtair deel en een lineair deel. Wat is juist over de fiscale aflossingseis?", [["Beide leningdelen voldoen aan de aflossingseis", "De aflossingseis vraagt minimaal annuïtair in 30 jaar; lineair lost sneller af en voldoet dus ook."], ["Alleen het annuïtaire deel voldoet aan de aflossingseis", "Lineair aflossen voldoet ook, omdat het sneller gaat dan annuïtair."], ["Alleen het lineaire deel voldoet, omdat annuïtair te traag aflost", "Annuïtair in 30 jaar is precies de minimumeis."], ["Geen van beide, omdat combinaties niet zijn toegestaan", "Combinaties van leningdelen zijn gewoon mogelijk."]], "1a.1"],
["Een klant wil zijn woning tijdelijk verhuren tijdens een werkperiode in het buitenland. Wat moet hij volgens de gangbare hypotheekvoorwaarden doen?", [["Vooraf toestemming vragen aan zijn geldverstrekker voor de verhuur", "Verhuur raakt de zekerheid van de geldverstrekker; de voorwaarden en het huurbeding vragen daarom voorafgaande toestemming."], ["Niets, verhuur van een eigen woning is altijd vrij toegestaan", "Hypotheekvoorwaarden beperken verhuur zonder toestemming, juist om de waarde van het onderpand te beschermen."], ["De verhuur alleen melden bij de gemeente waar de woning staat", "Een melding bij de gemeente vervangt de toestemming van de geldverstrekker niet."], ["De hypotheek eerst volledig oversluiten naar een andere geldverstrekker", "Oversluiten is niet nodig; de klant moet toestemming vragen aan zijn huidige geldverstrekker."]], "1e.11"],
["Een klant woont in een woning op erfpachtgrond en betaalt jaarlijks canon. Hoe wordt die canon in de inkomstenbelasting behandeld?", [["Die is als kosten van de eigen woning aftrekbaar in box 1", "Naast de hypotheekrente kunnen periodieke erfpachtbetalingen voor de eigen woning in box 1 worden afgetrokken."], ["De canon is niet aftrekbaar, omdat het een vorm van huur is", "Fiscaal geldt de periodieke canon voor de eigen woning juist als aftrekbare kosten, net als rente."], ["De canon verhoogt het eigenwoningforfait met hetzelfde bedrag", "De canon heeft geen invloed op het forfait; dat blijft een percentage van de WOZ-waarde."], ["De canon valt als schuld in box 3 van de erfpachter", "Een periodieke betaling is geen schuld; de canon is een aftrekpost in box 1."]], "1h.4"],
["Een woningcorporatie verkoopt een woning met korting op de marktwaarde, met de afspraak dat de corporatie de woning bij verkoop terugkoopt. Wat is kenmerkend voor zo'n koopconstructie?", [["De koper deelt bij verkoop de waardeontwikkeling met de corporatie, die de woning terugkoopt", "Tegenover de korting staat dat winst of verlies bij terugkoop volgens een afgesproken verdeling wordt gedeeld."], ["De koper betaalt geen hypotheekrente zolang hij de woning bewoont", "De koper financiert de verlaagde koopsom gewoon met een hypotheek en betaalt daarover rente."], ["De koper mag de woning bij verkoop vrij aan iedere derde verkopen tegen de dan geldende marktprijs", "Bij deze constructie geldt juist een terugkoopregeling met de corporatie."], ["De corporatie blijft eigenaar en de koper betaalt alleen huur", "De koper wordt juridisch eigenaar; dat onderscheidt deze constructie van huur."]], "1b.6"]
];
